// Lösungswege und Begründungen je Fall (id → k: Anfang der richtigen Antwort, w: Schritte, o: Begründung je Option)
window.WPR_LOES = Object.assign(window.WPR_LOES || {}, {"fb-4-gat1": {"k": "W muss nicht neu l", "w": ["Zwei Gefahren trennen: Muss W neu liefern (Leistungsgefahr)? Muss R zahlen (Preisgefahr)?", "Leistungsgefahr: Silvaner aus dem Großbestand = Gattungsschuld. Versand auf Wunsch des Käufers → Schickschuld. Konkretisierung mit Übergabe an den Paketdienst (§ 243 II) → Verlust danach → W frei (§ 275 I).", "Preisgefahr: Grundsätzlich entfiele der Preis (§ 326 I 1). Ausnahme Versendungskauf: Mit Übergabe an die Transportperson trägt der Käufer die Preisgefahr (§ 447 I).", "§ 475 II (Verbraucherschutz) greift nicht – R ist eine GmbH. Ergebnis: keine Neulieferung, R muss zahlen."], "o": ["Mit der Übergabe an den Paketdienst hat sich die Schickschuld konkretisiert (§ 243 II). Danach schuldet W nur noch diese Flaschen; sie sind verloren → W frei.", null, null, null, "W ist nach § 275 I frei, weil die konkretisierten Flaschen verloren sind. R muss zahlen (§ 447 I), bekommt aber keine neue Lieferung.", null]}, "rh6-16": {"k": "Beim absoluten Fix", "w": ["Wissensfrage zur Unmöglichkeit – jede Aussage an einer Norm prüfen.", "§ 275 I befreit nur von der Leistungspflicht; Sekundärpflichten (Schadensersatz, Surrogat) bleiben. § 311a I: anfängliche Unmöglichkeit lässt den Vertrag wirksam.", "§ 326 I 1 kennt Ausnahmen (§ 326 II, III). § 275 II und III sind Einreden.", "Fixgeschäft: relativ → Leistung nachholbar, Rücktritt ohne Frist; absolut → Zeitablauf führt zur Unmöglichkeit. Richtig ist also die Aussage zum absoluten Fixgeschäft."], "o": [null, null, null, null, null, null]}, "rh6-17": {"k": "P und S haben gege", "w": ["Vertragstyp: P handelt als Powerseller gewerblich (§ 14), S privat (§ 13), Vase = bewegliche Sache → Verbrauchsgüterkauf (§ 474 I).", "Leistung: Die ersteigerte Vase ist ein bestimmtes Stück → zerstört → P frei (§ 275 I).", "Preis: Beim Verbrauchsgüterkauf gilt § 447 grundsätzlich nicht (§ 475 II) – die Preisgefahr bleibt bis zur Übergabe bei P → S muss nicht zahlen (§ 326 I 1).", "Schadensersatz: P hat den Unfall (verursacht von Z) nicht zu vertreten. Ergebnis: keine gegenseitigen Ansprüche mehr."], "o": [null, null, null, null, "Schadensersatz setzt Vertretenmüssen voraus. Den Unfall hat allein Z verursacht – weder P noch T trifft ein Verschulden, das P zugerechnet werden könnte.", "Eine ersteigerte Vase ist ein konkretes Einzelstück (Stückschuld). Wie viele Vasen P sonst verkauft, ändert daran nichts."]}, "rh6-20": {"k": "Ja, weil mit der Ü", "w": ["Verbrauchsgüterkauf? Nein – zwei Privatleute. Also gilt § 447 ohne die Einschränkung des § 475 II.", "Versendungskauf: Auf Verlangen des K wird an einen anderen Ort als den Erfüllungsort (Wohnsitz des V, § 269 I) versandt. Dass V die Versandkosten trägt, macht daraus keine Bringschuld (§ 269 III).", "§ 447 I: Mit Übergabe an den Transportunternehmer geht die Preisgefahr auf K über.", "Vase zerstört → V frei (§ 275 I), aber K muss trotzdem 500 € zahlen."], "o": [null, null, null, null, "§ 447 I verteilt das Risiko nicht nach Verschulden. Ab Übergabe an den Transporteur trägt der Käufer die volle Preisgefahr.", null]}, "rh6-27": {"k": "ohne Rücksicht auf", "w": ["Nacherfüllung (§§ 437 Nr. 1, 439) ist ein Erfüllungsanspruch: Der Verkäufer hat versprochen, eine mangelfreie Sache zu liefern (§ 433 I 2).", "Weder § 437 Nr. 1 noch § 439 nennen Verschulden oder Kenntnis als Voraussetzung.", "Verschulden spielt erst beim Schadensersatz eine Rolle (§ 437 Nr. 3 → § 280 I 2)."], "o": ["Für die Nacherfüllung ist Verschulden ohne Bedeutung. Der Verkäufer muss nacherfüllen, auch wenn er den Mangel gar nicht verursacht hat.", "Vorsatz und grobe Fahrlässigkeit ist der Maßstab im Annahmeverzug (§ 300 I). Für die Nacherfüllung kommt es auf Verschulden gar nicht an.", "Das ist der Maßstab für Schadensersatz (§ 276 I). Die Nacherfüllung setzt kein Verschulden voraus.", "Kenntnis ist nur bei § 311a II oder § 442 (Kenntnis des Käufers) wichtig. Für die Nacherfüllungspflicht spielt sie keine Rolle.", null, "Die Nacherfüllung folgt aus dem Gesetz (§§ 437 Nr. 1, 439). Eine Garantie gäbe zusätzliche Rechte, ist aber nicht Voraussetzung."]}, "V-16": {"k": "Auf 8.000 €, weil ", "w": ["Minderung (§§ 437 Nr. 2, 441): Mangel liegt vor; Frist entbehrlich, weil H die Nachbesserung endgültig verweigert (§§ 323 II Nr. 1, 440).", "Berechnung nach § 441 III 1: geminderter Preis = Kaufpreis × (Wert mangelhaft : Wert mangelfrei).", "12.000 € × 10.000 / 15.000 = 8.000 €.", "Grund der Formel: Das ausgehandelte Preis-Wert-Verhältnis (K hat 20 % unter Wert gekauft) bleibt erhalten."], "o": [null, null, null, null, null, null]}, "V-17": {"k": "Rechte aus § 437 w", "w": ["Gestohlene Sache: K kann kein Eigentum erwerben, auch nicht gutgläubig (§ 935 I). A kann herausverlangen.", "Das ist ein Rechtsmangel (§ 435): P konnte K kein Eigentum verschaffen. Folgen über § 437 wie beim Sachmangel.", "Gewährleistungsausschluss: Zwischen Privatleuten grundsätzlich möglich – aber nicht, wenn der Verkäufer den Mangel arglistig verschweigt (§ 444). P wusste vom Diebstahl.", "Ergebnis: K hat Rechte aus § 437; P kann sich nicht auf den Ausschluss berufen."], "o": [null, null, null, null, null, null]}, "V-18": {"k": "Ja, bei neu herges", "w": ["E musste V gegenüber nacherfüllen (Mangel binnen eines Jahres, Vermutung § 477 I).", "Rückgriff gegen den Lieferanten: § 445a I – bei neu hergestellten Sachen kann der Verkäufer vom Lieferanten Ersatz der Aufwendungen verlangen, die er im Verhältnis zum Käufer nach § 439 II, III tragen musste.", "Dieser Anspruch ist Aufwendungsersatz, kein Schadensersatz → verschuldensunabhängig. Eine vorherige Zustimmung des L ist nicht nötig."], "o": [null, null, null, null, null, null]}, "rh6-31": {"k": "U kann ohne Frists", "w": ["Mangel: vereinbarte bzw. übliche Beschaffenheit ist eine Laufleistung von 15.000 km – tatsächlich 80.000 km (§ 434).", "Nacherfüllung? Nachbesserung unmöglich (die Laufleistung lässt sich nicht zurückdrehen), Nachlieferung unmöglich (einmaliges Fahrzeug) → beide Arten nach § 275 I ausgeschlossen.", "Ist die Nacherfüllung unmöglich, kann der Käufer ohne Fristsetzung zurücktreten (§§ 437 Nr. 2, 326 V) – verschuldensunabhängig.", "Der Mangel ist erheblich (§ 323 V 2), daher hat U die Wahl zwischen Rücktritt und Minderung."], "o": [null, null, null, null, null, null]}, "h9": {"k": "Nicht verjährt: Di", "w": ["Verjährung von Mängelansprüchen: grundsätzlich 2 Jahre ab Ablieferung (§ 438 I Nr. 3, II) – also bis März 2027.", "Verkürzung auf 1 Jahr bei gebrauchten Sachen? Beim Verbrauchsgüterkauf nur unter § 476 II: Der Verbraucher muss eigens in Kenntnis gesetzt und die Verkürzung ausdrücklich und gesondert vereinbart werden. Eine Klausel auf der Rückseite ohne Hinweis genügt nicht.", "Also nicht verjährt. Beweislast: Die Vermutung des § 477 I (1 Jahr) ist abgelaufen – Kerstin muss den Mangel bei Übergabe beweisen. Das Gutachten tut das.", "Ergebnis: Kerstin kann Reparatur verlangen."], "o": [null, null, null, null, null, null]}, "h10": {"k": "Ja, die Nachbesser", "w": ["Rücktritt (§§ 437 Nr. 2, 323) braucht grundsätzlich eine erfolglose Frist zur Nacherfüllung.", "Hoff durfte die Neulieferung wegen unverhältnismäßiger Kosten verweigern (§ 439 IV: 3.800 € vs. 140 €) – Clara war damit auf die Reparatur beschränkt.", "Entbehrlichkeit der Frist: § 440 S. 1 bei Fehlschlagen der Nacherfüllung. Nach dem zweiten erfolglosen Nachbesserungsversuch gilt sie als fehlgeschlagen (§ 440 S. 2).", "Ausschluss wegen Unerheblichkeit (§ 323 V 2)? Auslaufendes Wasser bei einem Kaffeeautomaten ist nicht unerheblich. Rücktritt wirksam."], "o": [null, null, null, "§ 475d gilt nur beim Verbrauchsgüterkauf. Clara kauft als Unternehmerin für ihr Café, also bleibt es bei §§ 323, 440.", null, null]}, "P3-vl6-0": {"k": "Kein Mangel: Eine ", "w": ["Sachmangel nach § 434 prüfen: subjektive Anforderungen (II), objektive (III), Montage (IV).", "Vertraglich vorausgesetzte Verwendung (II 1 Nr. 2): Beide Parteien müssen die Verwendung bei Vertragsschluss zugrunde legen – der Käufer muss sie mitteilen, der Verkäufer mittragen. F hat seinen Plan nie erwähnt.", "Objektiv (III): Der Drucker verarbeitet Papier wie alle Geräte dieser Klasse → übliche Beschaffenheit, Eignung für die gewöhnliche Verwendung.", "Ergebnis: kein Mangel. Eine Anfechtung nach § 119 II scheitert, weil der Irrtum nur F’s eigenes Motiv betrifft."], "o": [null, null, null, null, "Ein Drucker ist eine bewegliche Sache und wird gekauft (§ 433). Mit Werkleistungen hat das nichts zu tun.", null]}, "P3-vl6-1": {"k": "Kein Mangel: V wur", "w": ["Objektiv wäre ein ausgeblichener Bezug ein Mangel (§ 434 III). Die Parteien können aber eine geringere Qualität vereinbaren (negative Beschaffenheitsvereinbarung).", "Beim Verbrauchsgüterkauf nur unter § 476 I 2: (1) Der Verbraucher wird vor Vertragsschluss eigens über die Abweichung informiert, (2) sie wird ausdrücklich und gesondert vereinbart.", "V wurde die Stelle gezeigt, und sie unterschreibt vor Vertragsschluss einen eigenen Zusatz → beides erfüllt → die vereinbarte (schlechtere) Beschaffenheit ist geschuldet.", "Ergebnis: kein Mangel, kein neuer Bezug."], "o": [null, null, "§ 476 I 2 verlangt eigene Information und eine ausdrückliche, gesonderte Vereinbarung – aber keine notarielle Form.", null, "Es fehlt schon am Mangel, weil die geringere Qualität wirksam vereinbart wurde. Minderung setzt einen Mangel voraus.", null]}, "P3-vl6-2": {"k": "B hat keinen Anspr", "w": ["Objektiv hält ein üblicher Akku 60 km → der schwache Akku wiche von § 434 III ab.", "Objektive Anforderungen gelten aber nur, „soweit nicht wirksam etwas anderes vereinbart wurde“ (§ 434 III 1). A und B haben ausdrücklich „schwacher Akku, 15 km“ vereinbart.", "Strenge Voraussetzungen (§ 476 I 2) gelten nur beim Verbrauchsgüterkauf (Unternehmer verkauft an Verbraucher). Zwischen zwei Verbrauchern ist die Vereinbarung formlos wirksam.", "Ergebnis: kein Mangel, kein Anspruch."], "o": [null, "Für eine negative Beschaffenheitsvereinbarung zwischen Privatleuten gibt es keine Formvorschrift. Eine mündliche Vereinbarung reicht.", null, "Auch Privatverkäufer haften für Mängel. B hat nur deshalb keinen Anspruch, weil der schwache Akku wirksam vereinbart war.", null, null]}, "P3-vl6-3": {"k": "Kein Mangel, weil ", "w": ["Objektive Anforderungen (§ 434 III 1 Nr. 2 b): Die Sache muss die Beschaffenheit haben, die der Käufer nach öffentlichen Äußerungen des Herstellers (Werbung) erwarten kann.", "Ausnahme § 434 III 3: Der Verkäufer ist nicht gebunden, wenn die Äußerung im Zeitpunkt des Vertragsschlusses in derselben oder gleichwertigen Weise berichtigt war.", "H hat zwei Monate vor dem Kauf auf allen Kanälen berichtigt („3 Tage“) → K durfte nur noch 3 Tage erwarten → kein Mangel."], "o": [null, "Die Berichtigung wirkt objektiv: Entscheidend ist, dass sie vor Vertragsschluss gleichwertig veröffentlicht war – nicht, ob V sie kannte.", null, "§ 434 III 3 verlangt eine Berichtigung „in derselben oder gleichwertiger Weise“ – also öffentlich, nicht gegenüber jedem Käufer persönlich.", null, null]}, "P3-vl6-4": {"k": "Ein Mangel liegt v", "w": ["Objektive Anforderungen umfassen auch Probe und Muster: Die Sache muss der Probe entsprechen, die der Verkäufer vor Vertragsschluss zur Verfügung gestellt hat (§ 434 III 1 Nr. 3).", "Die Flaschen schmecken deutlich anders als die Probe → Abweichung → Sachmangel, auch wenn der Wein für sich trinkbar ist.", "Beide sind Kaufleute → K muss den Mangel unverzüglich rügen (§ 377 HGB), sonst verliert sie ihre Rechte. Zuerst Nacherfüllung."], "o": [null, null, "Auch unter Kaufleuten bestimmt eine Probe, was der Käufer erwarten darf (§ 434 III 1 Nr. 3). Eine Ausnahme für Kaufleute gibt es nicht – nur die Rügepflicht des § 377 HGB.", "§ 434 III 1 Nr. 3 knüpft schon an das bloße Zurverfügungstellen der Probe an. Eine schriftliche Verbindlichkeitserklärung ist nicht nötig.", "Geliefert wurde derselbe Wein, nur in schlechterer Qualität als die Probe. Das ist ein Sachmangel nach § 434, kein Fall für das Bereicherungsrecht.", "Auch bei Abweichung von der Probe gilt der Vorrang der Nacherfüllung. Zurücktreten kann K erst nach erfolgloser Frist (§§ 437 Nr. 2, 323)."]}, "P3-vl6-5": {"k": "Die Minderlieferun", "w": ["Seit 2022 gehört die Menge ausdrücklich zur vereinbarten Beschaffenheit (§ 434 II 2: „Art, Menge, Qualität …“).", "46 statt 50 Pakete → Abweichung in der Menge → die Lieferung ist mangelhaft (Sachmangel).", "Rechtsfolge: Nacherfüllung (§§ 437 Nr. 1, 439) – K kann die fehlenden 4 Pakete verlangen. Rücktritt erst nach erfolgloser Frist."], "o": [null, "Auf ein „Verdecken“ kommt es nicht an. Jede Abweichung von der vereinbarten Menge ist nach § 434 II 2 ein Sachmangel.", null, "Der Anspruch auf vollständige Lieferung bleibt bestehen. Die Minderlieferung ist ein Mangel, den V durch Nachlieferung beheben muss.", "Zuerst ist Nacherfüllung zu verlangen. Ein Rücktritt vom ganzen Vertrag wegen einer Teilminderung käme ohnehin nur bei Interessewegfall in Betracht.", "Ein Rechtsmangel (§ 435) betrifft Rechte Dritter an der Sache. Die Menge betrifft die Beschaffenheit, also Sachmangel."]}, "P3-vl6-6": {"k": "Ein Sachmangel lie", "w": ["Kauf mit Montageverpflichtung → für die Montage gilt § 434 IV: Die Sache ist mangelhaft, wenn die vereinbarte Montage durch den Verkäufer unsachgemäß durchgeführt wurde.", "Montiert hat der Subunternehmer S. Er ist Erfüllungsgehilfe des M (§ 278) – sein Fehler zählt wie ein eigener des M.", "Ergebnis: Sachmangel trotz fehlerfreien Schranks. K hat die Rechte aus § 437, zuerst Nacherfüllung nach seiner Wahl (§ 439 I)."], "o": [null, null, "Erfüllungsgehilfe ist jeder, den der Schuldner zur Erfüllung seiner Pflicht einsetzt – auch ein selbstständiger Subunternehmer.", "Vertragspartner des K ist M. Mängelrechte richten sich gegen M; S haftet allenfalls deliktisch, wenn er Eigentum verletzt.", "Der Schwerpunkt liegt auf der Lieferung des Schranks; die Montage ist Nebenpflicht. Es bleibt Kaufrecht – K wählt die Art der Nacherfüllung (§ 439 I).", "Im Kaufrecht gibt es kein Recht zur Selbstvornahme. K muss M Gelegenheit zur Nacherfüllung geben."]}, "P3-vl6-7": {"k": "Nach §§ 327 ff., w", "w": ["Abgrenzung: Ware mit digitalen Elementen (§ 327a III) liegt nur vor, wenn die Sache ihre Funktionen ohne das digitale Element nicht erfüllen kann.", "Das Telefon funktioniert ohne das Spiel einwandfrei → das Spiel ist nicht funktionsnotwendig.", "Dann gelten für das Spiel die Vorschriften über digitale Produkte (§§ 327 ff., vgl. §§ 327a II, 475a II), für das Telefon selbst normales Kaufrecht."], "o": [null, null, "Das vorinstallierte Spiel ist mitverkauft. Für Mängel digitaler Produkte gelten die §§ 327 ff. – ob es gesondert bezahlt wurde, spielt keine Rolle.", "Für Software gibt es keine Regel, die sie automatisch dem Werkvertrag zuordnet. Für digitale Produkte im Verbrauchervertrag gelten die §§ 327 ff.", null, "§ 823 I schützt Rechtsgüter wie Eigentum. Ein abstürzendes Spiel verletzt kein Rechtsgut, es ist ein Leistungsproblem."]}, "P3-vl6-8": {"k": "V kann von H Nache", "w": ["Laptop ohne Betriebssystem nicht nutzbar → Ware mit digitalen Elementen (§ 327a III) → beim Verbrauchsgüterkauf gelten §§ 475b ff.", "Objektive Aktualisierungspflicht (§ 475b IV Nr. 2): Der Verkäufer muss Updates, die für die Vertragsmäßigkeit nötig sind (v. a. Sicherheitsupdates), für den Zeitraum bereitstellen, den der Verbraucher üblicherweise erwarten kann.", "Bleiben sie aus, ist die Ware mangelhaft → V kann von H Nacherfüllung durch Bereitstellung verlangen. H kann den Hersteller einsetzen, bleibt aber verantwortlich.", "Upgrades (neue Funktionen) sind nicht geschuldet, außer vereinbart."], "o": [null, null, null, null, null, null]}, "P3-vl6-9": {"k": "Ein Mangel: Die Da", "w": ["„Inklusive Live-Verkehrsdaten“ → dauerhafte Bereitstellung digitaler Elemente vereinbart (§ 475c).", "§ 475c II: Der Unternehmer haftet dafür, dass die digitalen Elemente während des Bereitstellungszeitraums, mindestens aber zwei Jahre ab Ablieferung, vertragsgemäß sind.", "Der Dienst endet nach 14 Monaten → innerhalb der Mindestdauer → Mangel. Beweislast: Vermutung während des Bereitstellungszeitraums (§ 477 II)."], "o": [null, null, null, null, "Vertragspartner ist H. Er schuldet die dauerhafte Bereitstellung als Teil des Kaufvertrags und muss dafür einstehen.", "Für § 475c reicht, dass die vereinbarte Bereitstellung fehlt. Ob das Gerät daneben noch navigiert, ist ohne Bedeutung."]}, "fb-1-kfm": {"k": "S behält seine Män", "w": ["Rügeobliegenheit (§ 377 HGB) gilt nur beim beiderseitigen Handelskauf – beide Parteien müssen Kaufleute sein.", "Ist S Kaufmann? Kaufmann ist, wer ein Handelsgewerbe betreibt (§ 1 I HGB). Ein Kleingewerbe, das keinen kaufmännisch eingerichteten Geschäftsbetrieb braucht, ist kein Handelsgewerbe (§ 1 II HGB). Kaufmann würde S erst durch freiwillige Eintragung (§ 2 HGB).", "S ist nicht eingetragen → kein Kaufmann → § 377 HGB gilt nicht → Mängelrechte bleiben.", "Verbraucher ist S aber auch nicht: Er handelt gewerblich (§ 14) → kein Verbrauchsgüterkauf, kein § 477."], "o": [null, null, null, null, null, null]}, "fb-6-wlv": {"k": "Kaufrecht gilt (§ ", "w": ["Vertragstyp: Herstellung und Lieferung einer beweglichen Sache → Werklieferungsvertrag → Kaufrecht (§ 650 S. 1).", "Beide Parteien sind Kaufleute (GmbH, e. K.) → § 377 HGB; über § 381 II HGB gilt er auch für Werklieferungsverträge.", "Die Risse waren bei Lieferung sichtbar → R hätte unverzüglich untersuchen und rügen müssen. Nach sechs Wochen ist das zu spät → die Ware gilt als genehmigt (§ 377 II HGB)."], "o": [null, null, "Die Verjährung von zwei Jahren hilft nicht, wenn die Rechte schon durch die versäumte Rüge verloren sind. § 377 II HGB geht vor.", "Für herzustellende bewegliche Sachen gilt Kaufrecht (§ 650). Deshalb wählt der Käufer, nicht der Hersteller, die Art der Nacherfüllung.", null, "Die Risse waren schon bei Lieferung sichtbar, also offene Mängel. Sie hätten sofort gerügt werden müssen."]}, "P2-kauf1-0": {"k": "K kann von E Nache", "w": ["Smart-TV, dessen Streaming-Funktionen von Software abhängen → Ware mit digitalen Elementen; K ist Verbraucher → §§ 475b ff.", "Objektive Aktualisierungspflicht (§ 475b IV Nr. 2): Der Verkäufer muss Updates für den Zeitraum bereitstellen, den der Verbraucher erwarten kann – bei einem Fernseher deutlich länger als 14 Monate.", "Schuldner ist E, nicht der Hersteller. E kann sich beim Hersteller bzw. Lieferanten schadlos halten (§ 445a).", "Rechtsfolge: zuerst Nacherfüllung (Bereitstellung der Updates)."], "o": [null, null, null, null, "Die Aktualisierungspflicht folgt aus dem Gesetz (§ 475b IV Nr. 2). Eine Garantie wäre nur ein zusätzlicher Anspruch.", null]}, "P2-kauf1-1": {"k": "H haftet nicht, we", "w": ["Grundsätzlich wäre der Absturz ein Mangel einer Ware mit digitalen Elementen.", "§ 475b V: Der Unternehmer haftet nicht für einen Mangel, der allein auf eine fehlende Aktualisierung zurückgeht, wenn er den Verbraucher über das Update und die Folgen der Nichtinstallation informiert hat und der Verbraucher es trotzdem nicht installiert.", "H hat informiert und die Folgen erklärt; V hat nicht installiert → H haftet nicht."], "o": [null, null, null, "§ 475b V verlangt eine Information, aber keine Schriftform. Eine E-Mail genügt.", null, "Die Smartwatch ist eine Ware mit digitalen Elementen. Für sie gilt Kaufrecht (§§ 475b ff.), nicht § 327f."]}, "P2-kauf1-2": {"k": "Für die App gelten", "w": ["Entscheidend ist § 327a III: Ware mit digitalen Elementen nur, wenn die Sache ohne das digitale Element ihre Funktionen nicht erfüllen kann.", "Fahren und Motorunterstützung funktionieren ohne App → die App ist nicht funktionsnotwendig.", "Folge: Das E-Bike unterliegt normalem Kaufrecht; für die App gelten die §§ 327 ff. als eigenes digitales Produkt."], "o": [null, null, null, "Für digitale Produkte gelten die §§ 327 ff. Dass Software programmiert wird, macht den Vertrag nicht zum Werkvertrag.", "Die App ist ein eigenes digitales Produkt. Ihr Mangel löst eigene Rechte nach §§ 327 ff. aus, unabhängig davon, ob das Rad fährt.", "Welche Vorschriften gelten, bestimmt das Gesetz nach der Funktionsnotwendigkeit. Ein Wahlrecht des Käufers gibt es nicht."]}, "P2-kauf1-3": {"k": "Der Rost ist ein M", "w": ["Rost bei einem Gebrauchtwagen kann objektiv ein Mangel sein. H will die Sollbeschaffenheit durch die vorgedruckte Angabe absenken (negative Beschaffenheitsvereinbarung).", "Beim Verbrauchsgüterkauf ist das nur wirksam unter § 476 I 2: (1) Verbraucher vor Vertragsschluss eigens über die Abweichung informiert und (2) Abweichung ausdrücklich und gesondert vereinbart.", "Ein vorgedruckter Satz im Formular mit einer Unterschrift am Ende erfüllt weder „eigens“ noch „gesondert“ → Vereinbarung unwirksam → Rost ist ein Mangel."], "o": [null, null, null, null, "Arglist (§ 444) ist ein zusätzlicher Ausschlussgrund für Haftungsausschlüsse. Hier scheitert die Absenkung schon an § 476 I 2.", null]}, "P2-kauf1-4": {"k": "P kann sich nicht ", "w": ["Mangel: Ölverlust des Motors.", "Gewährleistungsausschluss „unter Ausschluss jeder Gewährleistung“: Zwischen Privatleuten grundsätzlich wirksam; § 476 gilt nicht (kein Verbrauchsgüterkauf).", "§ 444: Der Verkäufer kann sich nicht auf den Ausschluss berufen, wenn er den Mangel arglistig verschwiegen hat. P kannte den Ölverlust und schwieg – bei einem erheblichen, nicht erkennbaren Mangel besteht eine Offenbarungspflicht.", "Ergebnis: K hat Rechte aus § 437. Daneben könnte er nach § 123 anfechten."], "o": [null, null, null, "Es geht nicht um eine Garantie, sondern um arglistiges Verschweigen. Dafür genügt, dass P den Mangel kannte und nicht offenbarte.", null, null]}, "P2-kauf1-5": {"k": "H muss die Transpo", "w": ["Mangel (Naht reißt nach drei Wochen) → Vermutung des § 477 I beim Verbrauchsgüterkauf → K kann Nacherfüllung verlangen.", "Kosten: Der Verkäufer trägt alle zur Nacherfüllung erforderlichen Aufwendungen, ausdrücklich auch Transport-, Wege-, Arbeits- und Materialkosten (§ 439 II).", "Beim Verbrauchsgüterkauf kann der Verbraucher für diese Kosten einen Vorschuss verlangen (§ 475 IV nach deinem dtv).", "Der Ort der Reparatur ist dagegen kein Rücktrittsgrund."], "o": ["Wo die Nacherfüllung stattfindet, kann man diskutieren. Die Kosten des Transports trägt aber in jedem Fall der Verkäufer (§ 439 II).", null, null, null, "K hat Reparatur gewählt. Eine Neulieferung kann er nur verlangen, wenn er sie wählt – das hat er nicht.", null]}, "P2-kauf1-6": {"k": "G muss U die erfor", "w": ["Mangel der Fliesen (fehlerhafte Glasur). G hat neu geliefert – die Kosten für Herausreißen und Neuverlegen bleiben offen.", "§ 439 III: Hat der Käufer die mangelhafte Sache ihrer Art und ihrem Verwendungszweck gemäß eingebaut, muss der Verkäufer die erforderlichen Aufwendungen für Ausbau und Einbau ersetzen.", "Das gilt seit 2018 im allgemeinen Kaufrecht, also auch zwischen Unternehmern, und ist verschuldensunabhängig.", "Ausgeschlossen wäre es nur, wenn U den Mangel beim Einbau kannte (§§ 439 III 2, 442 I) – davon steht nichts im Sachverhalt."], "o": [null, null, null, "Der Fliesenleger hat ordnungsgemäß gearbeitet. Der Mangel liegt in der Kaufsache; dafür haftet der Verkäufer G nach § 439 III.", "§ 439 III sieht keine Kürzung vor. Zwischen Kaufleuten wäre nur die Rüge nach § 377 HGB zu beachten – sie ist hier nicht das Problem.", null]}, "P2-kauf1-7": {"k": "Der Händler kann d", "w": ["K wählt Neulieferung (§ 439 I). Der Verkäufer kann die gewählte Art verweigern, wenn sie nur mit unverhältnismäßigen Kosten möglich ist (§ 439 IV).", "Abwägung (§ 439 IV 2): Wert der mangelfreien Sache, Bedeutung des Mangels, ob die andere Art ohne erhebliche Nachteile für den Käufer möglich ist.", "Austausch eines Steuergeräts für 300 € beseitigt den Mangel vollständig; Neulieferung kostet 4.000 € → krasses Missverhältnis.", "Folge: K bleibt auf die Reparatur beschränkt (§ 439 IV 4). Kein Rücktritt, weil die Verweigerung berechtigt ist."], "o": [null, "Auch beim Verbrauchsgüterkauf darf der Verkäufer eine unverhältnismäßige Art der Nacherfüllung verweigern (§ 439 IV). Der Verbraucherstatus ändert daran nichts.", "§ 439 IV erlaubt nur, die unverhältnismäßige Art zu verweigern. Die andere Art – hier der Austausch des Steuergeräts – muss der Händler leisten.", "Der Händler verweigert berechtigt nur die Neulieferung und bietet die Reparatur an. Die Nacherfüllung ist nicht gescheitert, also kein Rücktritt.", null, null]}, "P2-kauf1-8": {"k": "V kann ohne weiter", "w": ["Rücktritt (§§ 437 Nr. 2, 323) braucht grundsätzlich eine erfolglose Frist zur Nacherfüllung.", "§ 440 S. 1: Frist entbehrlich, wenn die Nacherfüllung fehlgeschlagen ist. § 440 S. 2: Eine Nachbesserung gilt nach dem zweiten erfolglosen Versuch als fehlgeschlagen.", "Zwei Reparaturen, beide erfolglos → fehlgeschlagen → Rücktritt ohne weitere Frist. Rechtsfolge: Rückzahlung gegen Rückgabe (§ 346 I)."], "o": [null, "Ob der Händler sich bemüht hat, spielt keine Rolle. Nach dem zweiten erfolglosen Versuch gilt die Nachbesserung als fehlgeschlagen (§ 440 S. 2).", null, "Der Rücktritt ist verschuldensunabhängig. Es reicht, dass ein erheblicher Mangel vorliegt und die Nacherfüllung gescheitert ist.", "Für den Rücktritt muss die Sache zurückgegeben werden, aber nicht originalverpackt. Eine solche Voraussetzung gibt es nicht.", "Der Rücktritt führt zur Rückgewähr der Leistungen (§ 346 I). V bekommt Geld zurück, nicht nur eine Gutschrift."]}, "P2-kauf1-9": {"k": "Die Ware gilt als ", "w": ["Beide Kaufleute (e. K. und GmbH) → beiderseitiger Handelskauf → § 377 HGB.", "Der Käufer muss die Ware unverzüglich nach Ablieferung untersuchen und erkennbare Mängel unverzüglich rügen (§ 377 I HGB). Unterlässt er das, gilt die Ware als genehmigt (§ 377 II HGB).", "Ein offensichtlich verbogenes Teil wäre bei ordnungsgemäßer Untersuchung sofort aufgefallen. Rüge erst nach sechs Wochen → zu spät → Mängelrechte verloren.", "Ausnahme wäre nur Arglist des Verkäufers (§ 377 V HGB) – dafür fehlt jeder Anhaltspunkt."], "o": ["Bei Mängeln, die eine ordnungsgemäße Untersuchung gezeigt hätte, läuft die Rügefrist ab Ablieferung, nicht erst ab Entdeckung. Die Pflicht zur Untersuchung hat U versäumt.", "§ 377 HGB gilt für jeden beiderseitigen Handelskauf, egal ob Handelsware oder Investitionsgut.", "§ 377 HGB verlangt „unverzüglich“, also ohne schuldhaftes Zögern. Eine feste Frist von zwei Monaten gibt es nicht.", null, "Mit der Genehmigungsfiktion (§ 377 II HGB) sind alle Mängelrechte wegen dieses Mangels ausgeschlossen, auch eine anteilige Kostenübernahme.", null]}, "a6-3": {"k": "G kann von L einen", "w": ["Verbrauchsgüterkauf (privat, Händler). Mangel nach einem Jahr und drei Tagen.", "Beweislast: Die Vermutung des § 477 I gilt nur ein Jahr → G muss beweisen, dass der Mangel schon bei Übergabe vorlag. Verjährt ist aber nichts (2 Jahre, § 438 I Nr. 3).", "Kosten: Alle zur Nacherfüllung erforderlichen Aufwendungen, auch Transport, trägt der Verkäufer (§ 439 II). Beim Verbrauchsgüterkauf kann G dafür einen Vorschuss verlangen (§ 475 IV)."], "o": [null, null, "Der Nacherfüllungsanspruch ist mit dem Mangel und dem Verlangen fällig. Eine Frist braucht man erst für Rücktritt, Minderung und Schadensersatz statt der Leistung.", null, null, null]}, "a6-4": {"k": "Es handelt sich ni", "w": ["Abgrenzung nach § 327a III: Ware mit digitalen Elementen nur, wenn die Sache ihre Funktionen ohne das digitale Element nicht erfüllen kann.", "Der Kühlschrank kühlt auch manuell → Grundfunktion ohne KI erfüllt → nach h. M. keine Ware mit digitalen Elementen.", "Trotzdem gehört die Automatik zur geschuldeten Beschaffenheit; ihr Versagen ist ein Mangel."], "o": [null, "Die §§ 327 ff. gelten nur für Verbraucherverträge (Unternehmer an Verbraucher). Zwischen Unternehmern oder Privatleuten gelten sie nicht.", "„Ausschließlich“ ist falsch: Für den Kühlschrank selbst gilt Kaufrecht, für ein eigenständiges digitales Produkt ggf. §§ 327 ff. – nicht nur eine Norm.", null, null, null]}, "a6-5": {"k": "… Kaufpreis, Kaufg", "w": ["Essentialia negotii = die Punkte, über die sich die Parteien mindestens einigen müssen, damit ein Vertrag zustande kommt.", "Beim Kauf: Wer kauft von wem (Vertragsparteien), was (Kaufgegenstand) und zu welchem Preis.", "Alles andere (Leistungsort, Zahlungszeit, Gewährleistung) regelt notfalls das Gesetz (§§ 269, 271, 438)."], "o": [null, null, null, null, null, "Ohne Einigung über Parteien, Gegenstand und Preis gibt es keinen Kaufvertrag. Alles Weitere ergänzt das Gesetz."]}, "W-13": {"k": "Noch nicht; nach e", "w": ["Mangel: verkratzte Seitenwand. Kira hat sofort reklamiert (Rüge kein Problem).", "Rücktritt (§§ 437 Nr. 2, 323) braucht eine erfolglose Frist – oder einen Fall, in dem sie entbehrlich ist (§ 440).", "Fehlgeschlagen ist eine Nachbesserung in der Regel erst nach dem zweiten erfolglosen Versuch (§ 440 S. 2). Hier gab es erst einen.", "Ergebnis: Noch kein Rücktritt; Kira muss zunächst eine angemessene Frist setzen."], "o": [null, null, null, null, null, null]}, "W-14": {"k": "Nacherfüllung aus ", "w": ["Einordnung: Der Mäher ist nur über die App steuerbar → ohne das Digitale funktionslos → Ware mit digitalen Elementen → Kaufrecht (§§ 434, 475b).", "Mangel: Die Klingen lassen nach Wochen nach. Die Herstellerwerbung („langlebiges Klingensystem“) prägt die übliche Beschaffenheit (§ 434 III 1 Nr. 2 b).", "Zeitpunkt: Zeigt sich der Mangel innerhalb eines Jahres, wird vermutet, dass er bei Gefahrübergang vorlag (§ 477 I).", "Rechtsfolge: Nacherfüllung (§§ 437 Nr. 1, 439)."], "o": [null, null, null, null, null, null]}, "P2-kauf1-10": {"k": "Vermutet wird, das", "w": ["Verbrauchsgüterkauf; der Mangel zeigt sich nach elf Monaten.", "§ 477 I: Zeigt sich innerhalb eines Jahres seit Gefahrübergang ein Mangel, wird vermutet, dass er schon bei Gefahrübergang vorlag.", "Folge: Nicht K muss beweisen, sondern der Händler muss das Gegenteil beweisen (z. B. Bedienungsfehler)."], "o": [null, "Bis 2021 waren es sechs Monate. Seit 2022 gilt die Vermutung ein Jahr; sechs Monate gelten nur noch bei lebenden Tieren.", null, "§ 477 gilt für jeden Verbrauchsgüterkauf, ob im Laden oder online.", null, "Die Verjährung beträgt zwei Jahre (§ 438 I Nr. 3). Ein Jahr ist nur die Dauer der Beweislastumkehr."]}, "P2-kauf1-11": {"k": "Es wird vermutet, ", "w": ["Saugroboter mit dauerhaft bereitgestellter Software (3 Jahre vereinbart) → § 475c.", "Beweislast: Bei dauerhafter Bereitstellung gilt § 477 II statt der Jahresfrist: Zeigt sich der Mangel während des Bereitstellungszeitraums, wird vermutet, dass das digitale Element während der bisherigen Bereitstellung mangelhaft war.", "20 Monate liegen im vereinbarten Zeitraum → Vermutung greift → V hat Mängelrechte gegen den Verkäufer."], "o": [null, null, null, "Eine Grenze von einem Jahr gibt es für Softwarefehler nicht. Bei dauerhafter Bereitstellung kommt es auf den Bereitstellungszeitraum an.", null, "Auch ohne ausdrückliche Nennung schuldet der Verkäufer die objektiv übliche Funktion. Eine Kartierfunktion gehört bei diesem Gerät dazu."]}, "P2-kauf1-12": {"k": "Der Schrank ist ma", "w": ["Montageanforderungen (§ 434 IV): Bei einer zur Montage bestimmten Sache liegt ein Mangel auch vor, wenn die Anleitung mangelhaft ist und die Montage deshalb misslingt („IKEA-Klausel“).", "Die Anleitung ist so fehlerhaft, dass K die Rückwand falsch einbaut → der Schrank wackelt → Mangel, obwohl alle Teile einwandfrei sind.", "Das Risiko einer fehlerhaften Anleitung trägt der Verkäufer."], "o": [null, null, "Gerade die Selbstmontage durch den Käufer erfasst § 434 IV, wenn die Anleitung fehlerhaft war.", "K hat nur getan, was die Anleitung vorgibt. Das Risiko einer fehlerhaften Anleitung trägt nach § 434 IV der Verkäufer.", null, "§ 434 IV fragt nicht, ob der Käufer den Fehler hätte erkennen können. Nur bei positiver Kenntnis vom Mangel bei Vertragsschluss gilt § 442."]}, "P2-kauf1-13": {"k": "Die Falschlieferun", "w": ["Geliefert wurde etwas anderes als bestellt (aliud). Die Falschlieferung steht einem Sachmangel gleich (§ 434 V).", "Damit gelten die Mängelrechte des § 437 – mit dem Vorrang der Nacherfüllung: K muss zuerst Lieferung des richtigen Wassers verlangen (§ 439).", "Ein sofortiger Rücktritt scheitert an der fehlenden Frist (§ 323 I)."], "o": [null, "Die bloße Entgegennahme schließt Mängelrechte nicht aus. Nur bei Kenntnis des Mangels bei Vertragsschluss (§ 442) wären sie ausgeschlossen.", "Die Lieferung ist ein Versuch, den bestehenden Vertrag zu erfüllen – kein neues Angebot über eine andere Ware.", "Minderung setzt eine erfolglose Frist voraus. Zuerst hat K den Anspruch auf Nacherfüllung, also auf stilles Wasser.", null, null]}, "W-23": {"k": "Ja; R kauft als Un", "w": ["R kauft für seine Kanzlei → Unternehmer (§ 14) → kein Verbrauchsgüterkauf → § 475 II greift nicht.", "Leistung: Champagner = Gattungsschuld, Versand vereinbart → Schickschuld → Konkretisierung mit Übergabe an DHL (§ 243 II). Danach Bruch → W frei (§ 275 I).", "Preis: Versendungskauf → Preisgefahr geht mit Übergabe an die Transportperson auf den Käufer über (§ 447 I) → R muss zahlen."], "o": [null, null, null, null, null, null]}, "P2-kauf1-14": {"k": "Es liegt ein Recht", "w": ["Der Laptop gehört einem Leasingunternehmen, das ihn herausverlangt → V hat K nicht frei von Rechten Dritter übergeben.", "Rechtsmangel (§ 435 S. 1): Dritte können in Bezug auf die Sache Rechte gegen den Käufer geltend machen.", "Folgen über § 437 – verschuldensunabhängig für Nacherfüllung, Rücktritt, Minderung. Schadensersatz verlangt Vertretenmüssen.", "Der Kaufvertrag über eine fremde Sache ist wirksam; der Verkäufer haftet eben für die Rechtsmängelfreiheit (§ 433 I 2)."], "o": [null, "Für Nacherfüllung, Rücktritt und Minderung kommt es auf Verschulden nicht an. Dass V gutgläubig war, entlastet ihn nur beim Schadensersatz.", "Ein Kaufvertrag über eine fremde Sache ist wirksam. Er verpflichtet nur; dass V nicht Eigentümer war, führt zum Rechtsmangel.", "Gegen das Leasingunternehmen hat K nichts – es ist Eigentümer. Wegen des Rechtsmangels muss K sich an seinen Verkäufer V halten.", "Der Verkäufer schuldet die Sache frei von Rechten Dritter (§ 433 I 2), ohne dass der Käufer danach fragen muss.", null]}, "P2-kauf1-15": {"k": "Ein Mangel liegt v", "w": ["Bei H wurde nichts über Wasserdichtigkeit vereinbart → subjektiv kein Anspruch. Aber objektive Anforderungen (§ 434 III).", "§ 434 III 1 Nr. 2 b: Zur üblichen Beschaffenheit gehört, was der Käufer nach öffentlichen Äußerungen des Herstellers (Werbung) erwarten kann – „wasserdicht bis 2 Meter“.", "Ausnahmen (§ 434 III 3) liegen nicht vor. Defekt nach Bad in 1 Meter → Mangel. Rechte richten sich gegen den Verkäufer H."], "o": [null, null, null, "Mängelrechte bestehen nur gegenüber dem Vertragspartner, also H. Die Herstellerwerbung bestimmt nur, was H schuldet.", null, "Laut Werbung war ein Bad bis 2 Meter gerade unbedenklich. V hat das Handy so genutzt, wie es beworben wurde."]}, "fb-6-gef": {"k": "Beim ersten Gerät ", "w": ["§ 477 I: Zeigt sich ein Mangel innerhalb eines Jahres seit Gefahrübergang, wird vermutet, dass er schon bei Übergabe vorlag.", "Erstes Gerät: Ausfall nach 8 Monaten → Vermutung greift → H muss beweisen, dass V das Handy fallen gelassen hat.", "Zweites Gerät: Ausfall nach 14 Monaten → keine Vermutung mehr → V muss beweisen. Verjährt ist aber nichts (2 Jahre, § 438 I Nr. 3)."], "o": [null, null, null, null, null, null]}, "a6-11": {"k": "S kann den Vertrag", "w": ["Einordnung: Reine Software ohne körperliche Ware → digitales Produkt. S kauft privat von einem Unternehmer → Verbrauchervertrag → §§ 327 ff.", "Mangel: Das Programm stürzt regelmäßig ab (§ 327e). Vorrang: Anspruch auf Herstellung des vertragsgemäßen Zustands (§ 327l).", "F verweigert das kategorisch → der Verbraucher kann den Vertrag beenden (§ 327m I), ohne weitere Frist.", "Folge: Rückzahlung des Preises (§ 327o)."], "o": ["Ware mit digitalen Elementen setzt eine körperliche Sache voraus, die das Digitale enthält. Reine Software ist selbst das digitale Produkt.", null, "Für Verträge über digitale Produkte zwischen Unternehmer und Verbraucher gelten die §§ 327 ff. vorrangig, auch wenn es wirtschaftlich ein Kauf ist (§ 453 I 2).", "Schuldner ist der Vertragspartner F. Der Hersteller ist am Vertrag nicht beteiligt.", null, "§ 327m sieht die Vertragsbeendigung ausdrücklich vor, wenn der Unternehmer die Herstellung des vertragsgemäßen Zustands verweigert."]}, "a6-24": {"k": "Lukas hat keine An", "w": ["Was wurde vereinbart? Eine Reservierung mit Abholung „morgen zwischen 15 und 16 Uhr“ – Sophie hält das Armband nur in diesem Zeitfenster zurück.", "Lukas kam um 17 Uhr → die befristete Reservierung war abgelaufen; danach durfte Sophie frei verkaufen.", "Ohne fortbestehenden Anspruch keine Sekundäransprüche (Schadensersatz, § 285) und keine Beschaffungspflicht (Einzelstück)."], "o": ["Ein Anspruch auf das Armband hätte nur bestanden, solange die Reservierung galt. Sie war auf 15–16 Uhr befristet.", null, "Schadensersatz setzt eine Pflichtverletzung voraus. Sophie hat das Armband erst nach Ablauf der Reservierung verkauft – das war erlaubt.", "Eine Frist zur Nacherfüllung betrifft Mängel einer gelieferten Sache. Hier geht es um eine abgelaufene Reservierung.", null, null]}, "a6-27": {"k": "1, 4, 7, 8", "w": ["Nebenpflichten (Rücksichtnahmepflichten) stehen in § 241 II – Aussage 1 richtig.", "Sie bestehen bei allen Schuldverhältnissen, vertraglichen wie gesetzlichen (2 falsch). Ihre Verletzung löst keine Gewährleistungsrechte aus (3 falsch).", "Folgen: Schadensersatz (§§ 280 I, 282) und Rücktritt (§ 324) – Aussage 4 richtig. Die Abnahme ist eine Hauptpflicht des Käufers, keine § 241 II-Pflicht (5 falsch).", "Daraus folgt die Kombination 1, 4, 7, 8."], "o": [null, null, null, null, null, null]}, "a6-32": {"k": "Sie sind grundsätz", "w": ["Die Klausel will die geschuldete Beschaffenheit absenken (negative Beschaffenheitsvereinbarung). Grundsätzlich zulässig.", "Beim Verbrauchsgüterkauf aber nur unter § 476 I 2: Der Verbraucher wird vor Vertragsschluss eigens über die konkrete Abweichung informiert und sie wird ausdrücklich und gesondert vereinbart.", "Ein allgemeiner Satz im Vertragstext mit Unterschrift reicht nicht; zudem nennt er keinen konkreten Mangel (Verschluss).", "Ergebnis: unwirksam → die Kette muss den objektiven Anforderungen genügen; der defekte Verschluss ist ein Mangel."], "o": [null, null, null, "Eine Abweichung zulasten des Verbrauchers ist nur unter § 476 I 2 wirksam. Eine pauschale Formulierung im Vertrag erfüllt das nicht (§ 476 I 1).", null, null]}, "a6-35": {"k": "… ergänzen § 434 f", "w": ["§§ 475b, 475c gelten beim Verbrauchsgüterkauf über Waren mit digitalen Elementen.", "Sie treten neben § 434 und ergänzen ihn: Installation, Aktualisierungspflicht (Updates), dauerhafte Bereitstellung.", "Für reine digitale Produkte gelten die §§ 327 ff."], "o": [null, null, null, null, null, null]}, "a6-42": {"k": "H kann Nacherfüllu", "w": ["Mäher nur per App steuerbar → Ware mit digitalen Elementen → Kaufrecht (§§ 434, 475b), nicht §§ 327 ff. (§ 327a III).", "Fehlt die App bzw. funktioniert sie nicht, ist die Ware mangelhaft. Schuldner ist der Baumarkt als Verkäufer.", "Rechtsfolge zuerst Nacherfüllung durch Bereitstellung (§§ 437 Nr. 1, 439). Rücktritt erst nach erfolgloser Frist.", "Hinweis: Wenn der Mangel allein auf das nicht installierte Update zurückgeht, kann § 475b V die Haftung ausschließen – hier fehlt die App selbst."], "o": [null, "Die App ist Teil der geschuldeten Ware. Ein eigener Liefertermin für sie ist nicht nötig – sie muss bei Übergabe bereitstehen.", null, null, null, "Ohne App ist der Mäher nicht nutzbar. Zuerst kann H Nacherfüllung verlangen; Minderung kommt erst nach erfolgloser Frist in Betracht."]}, "a6-52": {"k": "K kann das e-Bike ", "w": ["E-Bike mit Software, die zur Ware gehört → Ware mit digitalen Elementen bzw. Sachmangel nach §§ 434, 475b. Vertragspartner ist H.", "Nacherfüllung: H muss den Mangel beheben. Dass er die Software nicht selbst ändern kann, macht die Nacherfüllung nicht unmöglich – er kann sich an S wenden.", "Kosten: Transport- und sonstige Kosten der Nacherfüllung trägt der Verkäufer (§ 439 II), beim Verbrauchsgüterkauf mit Vorschussanspruch (§ 475 IV)."], "o": [null, null, "Wo nacherfüllt wird, bestimmt sich nach den Umständen; eine generelle Abholpflicht des Verkäufers gibt es nicht. Die Kosten trägt aber er (§ 439 II).", null, null, null]}, "a6-53": {"k": "S muss das Öffnen ", "w": ["Die Hardware war mangelhaft (falsche Kabel), eingebaut gemäß ihrer Art und ihrem Zweck.", "§ 439 III: Der Verkäufer muss die erforderlichen Aufwendungen für Ausbau und Wiedereinbau ersetzen – hier Öffnen und Verschließen der Wände.", "Der Anspruch ist Teil der Nacherfüllung und deshalb verschuldensunabhängig."], "o": [null, "§ 439 III gibt gerade Ersatz für Aus- und Einbau. Das Öffnen der Wände gehört dazu und muss S bezahlen.", "Den Rückgriff gegen den Kabelhersteller muss S selbst nehmen (§ 445a). Gegenüber R haftet S als Verkäufer.", "Deliktisch müsste ein anderes Rechtsgut als die Kaufsache verletzt sein. Die Wände wurden planmäßig geöffnet, nicht beschädigt.", null, null]}, "fb-1-ver": {"k": "Z ist Verbraucheri", "w": ["Verbraucher ist, wer ein Rechtsgeschäft zu Zwecken abschließt, die überwiegend weder gewerblich noch selbstständig-beruflich sind (§ 13).", "Bei gemischter Nutzung entscheidet der überwiegende Zweck: 70 % privat → Z ist Verbraucherin, auch als Freiberuflerin.", "Verbrauchsgüterkauf → § 477 I: Mangel nach 10 Monaten → Vermutung, dass er bei Übergabe vorlag; E muss das Gegenteil beweisen."], "o": [null, null, null, null, null, null]}, "a6-65": {"k": "Ein Mangel liegt a", "w": ["Vereinbart war nichts → aber objektive Anforderungen (§ 434 III): Die Sache muss sich für die gewöhnliche Verwendung eignen. Ein Gewehr mit defektem Visier tut das nicht → Mangel.", "Zeitpunkt: Ein Tag nach Kauf → Vermutung des § 477 I beim Verbrauchsgüterkauf.", "Rechtsfolgen: Standardmodell – Reparatur oder Neulieferung; Sonderanfertigung (Stückschuld) – Reparatur, Neulieferung scheidet in der Regel aus."], "o": ["Auch ohne Vereinbarung schuldet der Verkäufer die objektiven Anforderungen (§ 434 III). Ein funktionierendes Visier gehört zur gewöhnlichen Verwendung.", "Zeigt sich der Mangel innerhalb eines Jahres, wird beim Verbrauchsgüterkauf vermutet, dass er schon bei Gefahrübergang vorlag (§ 477 I).", "Die Konkretisierung betrifft nur, welche Sache geschuldet ist. Sie befreit nicht von der Pflicht, diese Sache mangelfrei zu liefern.", null, null, "Auch bei einer Stückschuld bleibt die Reparatur möglich. Nur die Neulieferung scheidet in der Regel aus."]}, "a6-66": {"k": "F ist von der Nach", "w": ["Sondermodell = Stückschuld: Neulieferung scheidet aus (§ 275 I), es bleibt die Reparatur.", "Ist auch die Reparatur nicht möglich, ist die Nacherfüllung insgesamt unmöglich → F wird befreit (§ 275 I).", "B kann dann ohne Frist zurücktreten oder mindern (§ 326 V); Schadensersatz hängt vom Vertretenmüssen ab (§ 311a II bzw. § 283)."], "o": ["B hat zunächst einen Anspruch auf Mangelbeseitigung (Reparatur). Nur wenn diese unmöglich ist, wird F befreit.", null, "Beim Verbrauchsgüterkauf greift die Vermutung des § 477 I – B muss nicht beweisen, dass der Mangel bei Übergabe bestand.", "Ob F Schadensersatz schuldet, hängt davon ab, ob er den Mangel zu vertreten hat. Pauschal „in keinem Fall“ lässt sich das nicht sagen.", null, null]}, "a6-74": {"k": "Karl kann von Vict", "w": ["Mangel: Die Abgas-Manipulation führt zu einem Fahrverbot → das Fahrzeug eignet sich nicht für die gewöhnliche Verwendung (§ 434 III).", "Nacherfüllung (§§ 437 Nr. 1, 439) ist verschuldensunabhängig → Victor muss den Mangel beseitigen, soweit das möglich ist (§ 275).", "Schadensersatz (Taxikosten) setzt Vertretenmüssen voraus. Victor wusste nichts; der Hersteller ist nicht sein Erfüllungsgehilfe → kein Schadensersatz gegen Victor.", "Gegen VW gibt es mangels Vertrag keinen Nacherfüllungsanspruch (allenfalls Delikt, § 826)."], "o": [null, null, null, null, null, null]}, "a6-76": {"k": "Kurt kann von der ", "w": ["Maßgeblicher Zeitpunkt für die Mangelfreiheit ist der Gefahrübergang (§ 434 I), beim Kauf die Übergabe (§ 446).", "Der Marder beschädigte den Motorraum vor der Übergabe auf dem Hof der Händlerin → bei Übergabe war das Auto mangelhaft.", "Rechtsfolge: Nacherfüllung (§ 439) – verschuldensunabhängig; Minderung oder Rücktritt erst nach erfolgloser Frist."], "o": [null, "Nacherfüllung setzt kein Verschulden voraus. Es reicht, dass das Auto bei Übergabe mangelhaft war.", "Vor Minderung oder Rücktritt muss Kurt der Händlerin Gelegenheit zur Nacherfüllung geben (Vorrang der Nacherfüllung).", "Die Händlerin kann eine Art der Nacherfüllung verweigern, wenn sie unverhältnismäßig ist (§ 439 IV). „Unter keinen Umständen“ ist daher falsch.", null, null]}, "fb-6-ne1": {"k": "Ja, § 439 III gilt", "w": ["Mangelhafte Fliesen, eingebaut ihrer Art und ihrem Verwendungszweck gemäß (Verlegen im Neubau).", "§ 439 III: Der Verkäufer ersetzt die erforderlichen Aufwendungen für Ausbau und Einbau – unabhängig davon, wer eingebaut hat (hier ein Subunternehmer des Käufers).", "Die Norm steht im allgemeinen Kaufrecht → gilt auch zwischen Unternehmern; als Teil der Nacherfüllung verschuldensunabhängig."], "o": [null, null, null, null, null, null]}, "a6-79": {"k": "Die Vertragsstrafe", "w": ["Lieferung erst am 26.8. statt bis 13.8. → Verzug (Termin kalendermäßig bestimmt, § 286 II Nr. 1).", "Die Vertragsstrafe entsteht gerade durch die Verspätung und wird durch die spätere Lieferung nicht beseitigt → Verzögerungsschaden (§§ 280 I, II, 286).", "Kristin hat sogar auf die Vertragsstrafe hingewiesen. Ersatz neben der Leistung, ohne Frist."], "o": ["Es geht nicht um einen Anspruch des Dritten gegen Ludwig, sondern um Kristins eigenen Schaden. Den muss Ludwig als Verzögerungsschaden ersetzen.", "Behebbar wäre der Schaden nur, wenn eine spätere Lieferung ihn beseitigen würde. Die Vertragsstrafe bleibt aber fällig.", "Eine Frist braucht man für Schadensersatz statt der Leistung. Für Verzögerungsschäden genügt Verzug.", null, null, null]}, "L3-0": {"k": "U kann ohne Frists", "w": ["Mangel: tatsächliche Laufleistung 80.000 statt 15.000 km (§ 434).", "Nacherfüllung unmöglich: Die Laufleistung lässt sich nicht beseitigen, und bei einem Unikat gibt es kein gleichwertiges Ersatzfahrzeug (§ 275 I).", "Rücktritt ohne Fristsetzung (§§ 437 Nr. 2, 326 V). Der Mangel ist erheblich.", "Schadensersatz nach § 311a II scheitert, weil A die falsche Laufleistung nicht kannte und nicht kennen musste. Anfechtung (§ 119 II) ist nach Gefahrübergang verdrängt."], "o": [null, null, null, null, null, null]}, "fb-6-ne2": {"k": "Nein, A darf die N", "w": ["Mangel: klapperndes Handschuhfach. K wählt Neulieferung (§ 439 I).", "§ 439 IV: Der Verkäufer darf die gewählte Art verweigern, wenn sie unverhältnismäßige Kosten verursacht. Maßstab: Wert der mangelfreien Sache, Bedeutung des Mangels, Nachteile der anderen Art für den Käufer.", "Reparatur 120 € in 30 Minuten, vollständig und ohne Nachteil für K – Neulieferung eines 38.000-€-Wagens wäre völlig außer Verhältnis.", "Folge: K ist auf die Reparatur beschränkt; ein Rücktritt scheitert zudem an der Unerheblichkeit (§ 323 V 2)."], "o": [null, null, null, "Auch geringe Mängel muss der Verkäufer beseitigen. Unerheblichkeit sperrt nur Rücktritt und großen Schadensersatz, nicht die Nacherfüllung.", "A hat berechtigt verweigert und die Reparatur angeboten. Außerdem ist ein klapperndes Handschuhfach ein unerheblicher Mangel – Rücktritt ausgeschlossen (§ 323 V 2).", null]}, "L3-1": {"k": "Vermutet wird ein ", "w": ["Verbrauchsgüterkauf, Mangel (Kompressorausfall) nach acht Monaten.", "§ 477 I: Zeigt sich ein Mangel innerhalb eines Jahres, wird vermutet, dass er schon bei Übergabe vorlag. H müsste das Gegenteil (Bedienungsfehler) beweisen.", "Bleibt das Gutachten offen, geht das zu Lasten des H → V kann Nacherfüllung verlangen; die Kosten trägt H (§ 439 II)."], "o": [null, null, null, null, null, null]}, "fb-6-ne3": {"k": "Nein, weder die 90", "w": ["K hat selbst reparieren lassen, ohne H Gelegenheit zur Nacherfüllung zu geben.", "Im Kaufrecht gibt es kein Selbstvornahmerecht (anders §§ 536a II, 637). Kostenersatz bekäme K nur als Schadensersatz statt der Leistung – dafür braucht es eine erfolglose Frist (§ 281 I).", "Der BGH lehnt auch einen Ersatz der ersparten Aufwendungen des Verkäufers (§ 326 II 2 analog) ab, weil sonst der Vorrang der Nacherfüllung umgangen würde.", "Ergebnis: H muss nichts zahlen."], "o": [null, null, "Auch bei unstreitigem Mangel hat der Verkäufer das Recht zur zweiten Andienung. Er hätte vielleicht günstiger repariert oder getauscht – die Frist ist keine Förmelei.", "Die Chance zur Nacherfüllung muss vor der Reparatur bestehen. Eine nachträgliche Information gibt H diese Chance nicht mehr.", null, "Eine Bagatellgrenze gibt es nicht. Der Anspruch scheitert allein am fehlenden Recht zur Selbstvornahme."]}, "L3-2": {"k": "Kein Rücktritt; K ", "w": ["Mangel: Ein Neuwagen mit Lackkratzer entspricht nicht der üblichen Beschaffenheit (§ 434 III).", "Nacherfüllung: geschuldet, auch bei kleinen Mängeln. A hat die Ausbesserung angeboten.", "Rücktritt: ausgeschlossen bei unerheblicher Pflichtverletzung (§ 323 V 2) – ein 80-€-Kratzer an einem 32.000-€-Wagen ist unerheblich.", "Minderung bleibt möglich (§ 441 I 2), aber erst nach erfolgloser Frist und nur in Höhe des objektiven Minderwerts."], "o": [null, null, null, null, null, null]}, "L3-3": {"k": "Nein, der Ausschlu", "w": ["Mangel: Riss am Rahmen bei Übergabe.", "Gewährleistungsausschluss: Zwischen Privatleuten (kein Verbrauchsgüterkauf, § 474) individuell vereinbart → grundsätzlich wirksam. § 476 und die AGB-Kontrolle greifen nicht.", "Grenze § 444: Der Verkäufer kann sich nicht berufen, wenn er den Mangel arglistig verschwiegen oder eine Garantie übernommen hat. P kannte den Riss nicht → keine Arglist.", "Ergebnis: K hat keine Mängelrechte."], "o": [null, null, null, null, null, null]}, "L3-4": {"k": "B muss die Aus- un", "w": ["Mangel: Haarrisse in der Glasur, schon bei Übergabe angelegt.", "K hat die Fliesen ihrer Art und ihrem Zweck gemäß verlegen lassen.", "§ 439 III: Der Verkäufer muss die erforderlichen Aufwendungen für das Entfernen der mangelhaften und den Einbau der neuen Fliesen ersetzen – verschuldensunabhängig, bei allen Kaufverträgen.", "F hat fachgerecht gearbeitet und haftet nicht."], "o": [null, null, null, null, null, null]}, "L3-5": {"k": "Wegen des Getriebe", "w": ["Zwei Mängel getrennt prüfen.", "Getriebe: V hat den Schaden vor Vertragsschluss offengelegt; K kannte ihn → Rechte wegen dieses Mangels ausgeschlossen (§ 442 I 1).", "Kupplung: Davon wusste K nichts. § 442 I 1 schließt nur den bekannten Mangel aus. Grobe Fahrlässigkeit (§ 442 I 2) liegt nicht vor – aus dem Getriebehinweis musste K nicht auf weitere Mängel schließen.", "Ergebnis: Wegen der Kupplung kann K Nacherfüllung verlangen."], "o": [null, null, null, null, null, null]}, "L3-6": {"k": "Nein, weil V über ", "w": ["Smart-TV mit Betriebssystem → Ware mit digitalen Elementen; Verkäufer muss Updates bereitstellen (§ 475b IV Nr. 2) – das hat er getan.", "V hat das angebotene Update nicht installiert; der Fehler beruht allein darauf.", "§ 475b V: Dann haftet der Unternehmer nicht, wenn er über das Update und die Folgen der Nichtinstallation informiert hat und die Installation nicht an einer mangelhaften Anleitung scheiterte.", "Ergebnis: keine Haftung – auch keine anteilige."], "o": [null, null, null, null, null, null]}, "L3-7": {"k": "V kann den Vertrag", "w": ["Jahresabo für Streaming → digitales Produkt → §§ 327 ff.", "S hat nach Vertragsschluss nichts bereitgestellt (kein Zugangslink).", "§ 327c I: Bleibt die Bereitstellung aus und stellt der Unternehmer auch nach Aufforderung nicht unverzüglich bereit, kann der Verbraucher den Vertrag beenden. Eine bestimmte Fristlänge ist nicht vorgeschrieben.", "Folge: Rückzahlung bereits gezahlter Beträge (§ 327o)."], "o": [null, null, null, null, null, null]}, "L3-8": {"k": "Nein, es fehlt ein", "w": ["Schadensersatz statt der Leistung für einen Ersatzkauf: §§ 437 Nr. 3, 280 I, III, 281.", "§ 281 I verlangt eine erfolglos abgelaufene angemessene Frist zur Nacherfüllung. Ein Anruf, in dem der Defekt geschildert wird, ist keine Fristsetzung (keine Aufforderung mit Zeitgrenze).", "Entbehrlich wäre die Frist bei Verweigerung oder besonderen Umständen (§ 281 II, § 440) – nicht ersichtlich. Für Unternehmer gibt es keine Ausnahme.", "Ergebnis: Kein Schadensersatz statt der Leistung; auch Minderung bräuchte eine Frist."], "o": [null, null, null, null, null, null]}, "fb-7-min": {"k": "Der Verkäufer muss", "w": ["Minderung (§ 441): Frist erfolglos → möglich.", "Formel (§ 441 III): geminderter Preis = Kaufpreis × Wert mangelhaft / Wert mangelfrei = 1.200 × 1.000 / 1.500 = 800 €.", "Erstattung (§ 441 IV): gezahlt 1.200 € − geminderter Preis 800 € = 400 €.", "Das gute Geschäft (20 % unter Wert) bleibt durch die Verhältnisrechnung erhalten."], "o": [null, null, null, "Geminderter Preis 1.200 × 1.000/1.500 = 800 €. K hat 1.200 € gezahlt, also 400 € zu viel (§ 441 III, IV).", null, "Die Minderung folgt der Verhältnisformel des § 441 III. Für eine pauschale Halbierung gibt es keine Grundlage."]}, "PK-12": {"k": "U muss zahlen, wei", "w": ["Kauf zwischen Unternehmern; auf Wunsch des Käufers Versand an einen anderen Ort als den Erfüllungsort (Köln) → Versendungskauf.", "§ 447 I: Mit Übergabe an die Spedition geht die Preisgefahr auf den Käufer über. § 475 II greift nicht (kein Verbraucher).", "Leistungsgefahr: Gattungsschuld, mit Übergabe an die Spedition konkretisiert (§ 243 II) → H frei (§ 275 I).", "Ergebnis: U muss zahlen, bekommt aber keine neue Lieferung."], "o": [null, null, null, null, null, null]}, "PK-13": {"k": "K kann 300 € zurüc", "w": ["Minderung nach erfolgloser Frist zulässig (§§ 437 Nr. 2, 441).", "§ 441 III: 900 € × 800 / 1.200 = 600 € geminderter Preis.", "K hat 900 € gezahlt → 300 € zurück (§ 441 IV). Bei der Minderung behält er den Roller."], "o": [null, "Der Vergleich von Kaufpreis und Ist-Wert ist nicht der Maßstab. § 441 III setzt Wert mit und ohne Mangel ins Verhältnis und wendet es auf den Preis an.", null, "Eine Pauschalminderung um die Hälfte gibt es nicht. Maßgeblich ist allein die Verhältnisrechnung.", null, null]}, "PK-14": {"k": "V hat einen Anspru", "w": ["Zwei Anspruchsgegner trennen: Verkäufer E (gesetzliche Mängelrechte) und Hersteller H (Garantie).", "Gegen E: Mängelrechte verjähren in zwei Jahren ab Ablieferung (§ 438 I Nr. 3) – nach drei Jahren verjährt. Die Herstellergarantie verlängert sie nicht.", "Gegen H: Die Garantieerklärung begründet einen eigenen Anspruch (§ 443 I) zu den Bedingungen der Garantie – 5 Jahre Funktionsfähigkeit."], "o": [null, null, "Garantiegeber ist der Hersteller H. E hat keine eigene Garantie abgegeben und haftet daraus nicht.", null, null, "Die Garantie gibt Rechte zu den in ihr genannten Bedingungen, typischerweise Reparatur. Ein Rücktrittsrecht folgt daraus nicht."]}, "fb-6-dig": {"k": "Ja, fehlende Updat", "w": ["Smart-TV, dessen Apps von der Software abhängen → Ware mit digitalen Elementen (§ 327a III); Verbrauchsgüterkauf (März 2026 – noch altes Recht, im Ergebnis gleich).", "Objektive Aktualisierungspflicht des Verkäufers (§ 475b IV Nr. 2): Updates für den Zeitraum, den der Verbraucher üblicherweise erwarten kann – bei einem TV deutlich mehr als sieben Monate.", "Bleiben sie aus, ist die Ware mangelhaft. Schuldner ist E, nicht der Hersteller (E kann Regress nehmen)."], "o": [null, null, null, null, null, null]}, "P2-kauf2-10": {"k": "Es wird vermutet, ", "w": ["Haltbarkeitsgarantie: Der Garantiegeber übernimmt, dass die Sache für eine bestimmte Dauer eine bestimmte Beschaffenheit behält (§ 443 II).", "Gesetzliche Vermutung: Ein während der Geltungsdauer auftretender Sachmangel begründet die Rechte aus der Garantie (§ 443 II).", "Folge: Nicht K muss richtige Bedienung beweisen; H muss beweisen, dass ein Bedienungsfehler den Ausfall verursacht hat."], "o": [null, null, "Eine Garantie ist eine freiwillige Zusage und darf länger laufen als die gesetzliche Gewährleistung.", "Die Herstellergarantie ist ein eigener Anspruch gegen den Hersteller. Die Gewährleistung des Händlers bleibt davon unberührt.", "Die Vermutung des § 443 II gilt für die gesamte Geltungsdauer der Garantie, hier fünf Jahre.", "Die Garantie verspricht gerade fünf Jahre volle Funktionsfähigkeit. Ein Pumpenausfall nach drei Jahren ist ein Garantiefall."]}, "P2-kauf2-11": {"k": "K kann Nacherfüllu", "w": ["Ausschluss der Mängelrechte wegen Kenntnis (§ 442 I 1) knüpft an die Kenntnis bei Vertragsschluss an.", "K hat den Riss erst bei Lieferung gesehen, also nach Vertragsschluss → § 442 greift nicht.", "Eine Rügepflicht wie § 377 HGB trifft Verbraucher nicht; die vorbehaltlose Annahme ist kein Verzicht.", "Ergebnis: K kann Nacherfüllung verlangen (beim Verbrauchsgüterkauf hilft zudem § 477 I)."], "o": ["§ 442 I 1 stellt auf die Kenntnis bei Vertragsschluss ab. Wer den Mangel erst bei Übergabe bemerkt, behält seine Rechte.", "§ 377 HGB gilt nur beim beiderseitigen Handelskauf. K ist Verbraucher.", "Ein Verzicht auf Rechte setzt eine entsprechende Erklärung voraus. Die bloße Entgegennahme der Ware ist keine solche Erklärung.", "Das BGB kennt keine Beschränkung auf Minderung bei Kenntnis bei Übergabe. Die Rechte bleiben vollständig erhalten.", null, "Eine Anzeigefrist von 14 Tagen gibt es für Verbraucher nicht. Grenze ist nur die Verjährung (§ 438)."]}, "P2-kauf2-12": {"k": "E kann von L die A", "w": ["E musste gegenüber K nacherfüllen (neues Notebook, Mangel bei Übergabe).", "Unternehmerrückgriff (§ 445a I): Bei neu hergestellten Sachen kann der Verkäufer von seinem Lieferanten Ersatz der Aufwendungen verlangen, die er im Verhältnis zum Käufer nach § 439 II, III zu tragen hatte – wenn der Mangel schon beim Übergang auf den Verkäufer vorhanden war.", "Der Anspruch ist Aufwendungsersatz, also verschuldensunabhängig, und richtet sich gegen den eigenen Lieferanten L."], "o": ["E war gegenüber K zur Nacherfüllung verpflichtet. Er hat nicht freiwillig repariert, sondern eine gesetzliche Pflicht erfüllt.", null, "Der Rückgriff läuft entlang der Lieferkette: E gegen seinen Vertragspartner L, L gegen seinen Lieferanten (§ 445a III).", null, "§ 445a I erfasst gerade die Aufwendungen der Nacherfüllung, also auch Reparaturkosten.", "Für den Rückgriff ist der Vertriebsweg gleichgültig. Es kommt nur auf die Nacherfüllungspflicht gegenüber dem Käufer an."]}, "P2-kauf2-13": {"k": "Wirksam: Seit der ", "w": ["Rücktritt braucht grundsätzlich eine erfolglose Frist (§ 323 I).", "Beim Verbrauchsgüterkauf genügt nach § 475d I Nr. 1: Der Unternehmer hat die Nacherfüllung trotz Ablaufs einer angemessenen Frist ab der Mangelmitteilung nicht vorgenommen – eine ausdrückliche Fristsetzung ist nicht nötig.", "V meldete den Mangel; H reagierte vier Wochen nicht, obwohl eine Woche gereicht hätte → angemessene Frist abgelaufen.", "Ein Akkuausfall ist erheblich → Rücktritt wirksam."], "o": [null, null, null, "Der Rücktritt ist verschuldensunabhängig. Es kommt nur auf den Mangel und den Fristablauf an.", "Die Nutzung schließt den Rücktritt nicht aus; sie führt nur zu Wertersatz für gezogene Nutzungen (§ 346).", null]}, "fb-7-vgk2": {"k": "Nein, die Verjähru", "w": ["Regel: Verjährung 2 Jahre ab Ablieferung (§ 438 I Nr. 3, II) → wäre am 1. März 2026 abgelaufen.", "Beim Verbrauchsgüterkauf: Hat sich der Mangel innerhalb der Verjährungsfrist gezeigt, tritt die Verjährung nicht vor Ablauf von vier Monaten nach dem ersten Auftreten ein (§ 475e III).", "Erstes Auftreten 15. Februar 2026 → Verjährung frühestens 15. Juni 2026. Das Verlangen am 1. Juni ist rechtzeitig."], "o": [null, null, null, null, null, null]}, "P2-kauf2-14": {"k": "K schuldet keinen ", "w": ["Liefert der Verkäufer eine neue Sache, kann er die mangelhafte zurückverlangen – nach den Rücktrittsregeln (§ 439 VI 1, §§ 346 ff.), die grundsätzlich auch Nutzungsersatz umfassen.", "Beim Verbrauchsgüterkauf ordnet § 475 III 1 aber an: Nutzungen sind nicht herauszugeben und ihr Wert nicht zu ersetzen.", "K gibt die alte Maschine zurück, schuldet aber nichts für sechs Monate Nutzung."], "o": [null, null, null, "Auf ein Verschulden des H kommt es nicht an. Der Ausschluss des Nutzungsersatzes folgt allein aus § 475 III 1.", null, "Der Verkäufer kann die mangelhafte Sache zurückverlangen (§ 439 VI 1). K darf sie nicht behalten."]}, "PK-31": {"k": "G behält seine Rec", "w": ["Beiderseitiger Handelskauf (Kaufmann G, GmbH als Formkaufmann) → § 377 HGB.", "Untersuchung: Bei großen Mengen genügen repräsentative Stichproben. G hat sofort geprüft – ohne Befund, weil der Fehler verdeckt war.", "Verdeckter Mangel: Er muss unverzüglich nach Entdeckung gerügt werden (§ 377 III HGB). G hat das getan → Rechte bleiben.", "Vorrang der Nacherfüllung gilt weiterhin."], "o": [null, null, null, null, null, null]}, "P2-kauf2-0": {"k": "320 €, weil der Pr", "w": ["Minderung nach erfolgloser Frist (§§ 437 Nr. 2, 441).", "§ 441 III: geminderter Preis = 800 € × 600 / 1.000 = 480 €.", "Erstattung: 800 € gezahlt − 480 € = 320 €. K behält das Rad."], "o": [null, null, null, "Die Minderung setzt keinen Verlust voraus. Sie stellt das vereinbarte Preis-Wert-Verhältnis auch beim günstigen Kauf wieder her.", "Eine Halbierungsregel gibt es nicht. Allein die Verhältnisrechnung des § 441 III entscheidet.", null]}, "P2-kauf2-1": {"k": "V kann Nacherfüllu", "w": ["Mangel: Konstruktionsfehler. Rechte aus § 437 prüfen und nach Verschulden sortieren.", "Verschuldensunabhängig: Nacherfüllung, Rücktritt, Minderung – stehen V zu.", "Schadensersatz (Verbrennungen, Schmerzensgeld) nach §§ 437 Nr. 3, 280 I setzt Vertretenmüssen des H voraus. H konnte den Fehler nicht erkennen; der Hersteller ist nicht sein Erfüllungsgehilfe → kein Schadensersatz gegen H.", "Für den Körperschaden haftet der Hersteller (ProdHaftG, § 823 I)."], "o": [null, null, null, null, null, null]}, "P2-kauf2-2": {"k": "G kann die 300 € a", "w": ["Schaden: Einweggeschirr während des Ausfalls → entsteht durch den Mangel selbst, eine spätere Nacherfüllung beseitigt ihn nicht → Schadensersatz neben der Leistung (§§ 437 Nr. 3, 280 I), ohne Frist und ohne Verzug.", "Vertretenmüssen wird vermutet (§ 280 I 2); H hätte den Mangel bei der Endkontrolle bemerkt → Fahrlässigkeit.", "Ergebnis: 300 €."], "o": [null, null, null, "§ 284 betrifft Aufwendungen, die durch den Ausfall nutzlos werden. Das Einweggeschirr ist ein Schaden, der durch den Mangel entstanden ist.", null, null]}, "P2-kauf2-3": {"k": "K kann zurücktrete", "w": ["Mehrkosten des Ersatzkaufs = Schadensersatz statt der Leistung (§§ 437 Nr. 3, 280 I, III, 281).", "Frist entbehrlich: H verweigert ernsthaft und endgültig (§ 281 II, § 440).", "Vertretenmüssen wird vermutet. Rücktritt und Schadensersatz sind kombinierbar (§ 325)."], "o": [null, null, "Die Mehrkosten eines Deckungskaufs sind der typische Schadensersatz statt der Leistung. „Nie“ ist falsch.", null, "Für eine Kürzung nach § 254 müsste K etwas falsch gemacht haben. Ein angemessener Deckungskauf ist kein Mitverschulden.", "Die Nutzung schließt weder Rücktritt noch Schadensersatz aus; beim Rücktritt sind nur Nutzungen herauszugeben."]}, "P2-kauf2-4": {"k": "K kann statt Schad", "w": ["Rücktritt wirksam (erheblicher Mangel, erfolglose Frist).", "Die Markise ist kein Schaden aus der Nichtleistung, sondern eine Aufwendung, die K im Vertrauen auf den Wohnwagen gemacht hat und die mit dem Rücktritt nutzlos wird.", "§ 284: Anstelle des Schadensersatzes statt der Leistung kann der Käufer vergebliche Aufwendungen ersetzt verlangen – Voraussetzung ist, dass ein solcher Schadensersatzanspruch dem Grunde nach besteht (Vertretenmüssen des H vermutet).", "Der Rücktritt schließt das nicht aus (§ 325)."], "o": [null, "Gerade weil die Markise nicht Teil des Kaufs war, kommt § 284 in Betracht: Er ersetzt Aufwendungen, die der Käufer im Vertrauen auf die Leistung bei Dritten gemacht hat.", "Für § 284 genügt, dass H den Mangel zu vertreten hat – Fahrlässigkeit reicht, und sie wird vermutet (§ 280 I 2).", null, null, null]}, "P2-kauf2-5": {"k": "Nicht verjährt, we", "w": ["Regel: Verjährung 2 Jahre ab Ablieferung → 1. März 2026.", "Verbrauchsgüterkauf: Zeigt sich der Mangel innerhalb der Verjährungsfrist, tritt die Verjährung nicht vor vier Monaten nach dem ersten Auftreten ein (§ 475e III).", "Erstes Auftreten 15. Januar 2026 → frühestens 15. Mai 2026. Das Verlangen am 1. Mai ist rechtzeitig."], "o": [null, "Für Mängelansprüche gilt die Sonderregel des § 438 (zwei Jahre ab Ablieferung), nicht die Regelverjährung.", "Eine Rügefrist trifft Verbraucher nicht. Grenze ist nur die Verjährung.", "Die Entdeckung des Mangels lässt die Frist nicht neu beginnen. Sie führt nur zur viermonatigen Ablaufhemmung (§ 475e III).", null, null]}, "P2-kauf2-6": {"k": "Die Verjährung tri", "w": ["Verbrauchsgüterkauf; der Verkäufer hat im Rahmen der Nacherfüllung repariert.", "§ 475e IV: Für den geltend gemachten Mangel tritt die Verjährung nicht vor Ablauf von zwei Monaten nach dem Zeitpunkt ein, in dem die nachgebesserte Ware dem Verbraucher übergeben wurde (Ablaufhemmung).", "Rückgabe am 1. Juli → frühestens Verjährung am 1. September – außerdem läuft die reguläre Zweijahresfrist ohnehin länger."], "o": [null, null, null, "Das Gesetz sieht keine Hemmung für die Reparaturdauer mit festen sechs Monaten vor. § 475e IV: nicht vor zwei Monaten nach Übergabe der reparierten Ware.", null, "Nach deinem dtv-Stand gibt es das nicht. Eine Verlängerung um 12 Monate nach Reparatur (§ 475e V) gilt erst für Verträge ab 31.07.2026 – hier wurde im Vorjahr gekauft."]}, "P2-kauf2-7": {"k": "U muss zahlen, wei", "w": ["Kauf zwischen Unternehmern; auf Verlangen des Käufers Versand an einen anderen Ort als den Erfüllungsort → Versendungskauf.", "§ 447 I: Mit Übergabe an die Spedition trägt der Käufer die Preisgefahr. § 475 II greift nicht.", "Leistung: konkretisiert mit Übergabe an die Spedition (§ 243 II) → H frei (§ 275 I). Ergebnis: U zahlt, keine Neulieferung."], "o": [null, null, null, null, "Die Preisgefahr geht nach § 447 I unabhängig davon über, wie sorgfältig die Spedition ausgewählt wurde.", null]}, "P2-kauf2-8": {"k": "S muss nicht zahle", "w": ["S (Studentin, privat) kauft beim Online-Händler → Verbrauchsgüterkauf.", "§ 475 II: § 447 I gilt nur, wenn der Verbraucher den Transporteur selbst beauftragt hat und der Unternehmer ihn nicht vorher benannt hat. Hier beauftragte O den Paketdienst.", "Also bleibt es bei § 446: Die Preisgefahr geht erst mit Übergabe an S über. Ohne Übergabe entfällt der Kaufpreis (§ 326 I 1) – O trägt das Versandrisiko."], "o": [null, null, null, null, "Auf ein Auswahlverschulden kommt es nicht an. § 475 II verlagert das Versandrisiko beim Verbrauchsgüterkauf generell auf den Unternehmer.", "S muss gar nicht zahlen, weil die Preisgefahr noch bei O lag. Ansprüche gegen den Paketdienst hat O."]}, "P2-kauf2-9": {"k": "V kann sich nicht ", "w": ["Mangel: Die Kamera ist nicht wasserdicht bis 10 Meter.", "V hat die Wasserdichtigkeit garantiert (Beschaffenheitsgarantie, § 443). Wer eine Garantie übernommen hat, kann sich auf einen Gewährleistungsausschluss nicht berufen (§ 444).", "Zusätzlich: Verbrauchsgüterkauf → ein Ausschluss zulasten des Verbrauchers ist ohnehin unwirksam (§ 476 I).", "Ergebnis: K hat die Rechte aus § 437 – zuerst Nacherfüllung. Der Vertrag bleibt im Übrigen wirksam."], "o": [null, "Bei einer Beschaffenheitsgarantie haftet der Verkäufer für das Versprochene, egal ob er den Mangel kannte.", null, "Unwirksam ist nur die Ausschlussklausel, nicht der ganze Vertrag. Der Kauf bleibt bestehen.", "Zuerst kann K Nacherfüllung verlangen. Dass die Kamera an Land funktioniert, ändert nichts am Mangel.", null]}, "rh6-1": {"k": "Ein Unternehmer al", "w": ["Definition des § 474 I 1: Ein Verbraucher (§ 13) kauft von einem Unternehmer (§ 14) eine Ware.", "Ware = bewegliche Sache. Grundstücke sind ausgeschlossen.", "Rollen müssen genau so verteilt sein: Unternehmer verkauft, Verbraucher kauft. Der Vertriebsweg (online oder Laden) ist gleichgültig."], "o": [null, null, null, null, null, null]}, "fb-7-gar": {"k": "Gegen H nicht mehr", "w": ["Zwei Anspruchsgegner trennen: Händler H (gesetzliche Mängelrechte) und Hersteller (Garantie).", "Gegen H: Verjährung 2 Jahre ab Ablieferung (§ 438 I Nr. 3) → Mai 2025 abgelaufen. Die Herstellergarantie verlängert das nicht.", "Gegen den Hersteller: Haltbarkeitsgarantie (§ 443 I, II) über 5 Jahre → Getriebeausfall im Juni 2026 liegt in der Garantiezeit; vermutet wird ein Garantiefall."], "o": [null, "Gewährleistung und Garantie sind unabhängig. Die Garantie läuft hier fünf Jahre, auch wenn die Gewährleistung schon verjährt ist.", "Gegen H ist die Gewährleistung verjährt. Gesamtschuldner sind H und Hersteller nicht – es sind zwei verschiedene Ansprüche.", null, null, null]}, "fb-7-dp": {"k": "Ja, die §§ 327 ff.", "w": ["Vertrag über ein digitales Produkt (App) zwischen Unternehmer und Verbraucher → §§ 327 ff.", "Preis? K zahlt kein Geld, stellt aber personenbezogene Daten bereit. § 327 III stellt das einem Preis gleich – die Vorschriften gelten also.", "Mangel: Die App stürzt seit einem Update ab. Auch Aktualisierungen müssen vertragsgemäß sein (§ 327f).", "Rechtsfolge: Rechte nach § 327i (Herstellung des vertragsgemäßen Zustands, Vertragsbeendigung)."], "o": [null, "Für Verbraucherverträge über digitale Produkte gelten die §§ 327 ff. vorrangig. Das Kaufrecht des § 453 tritt insoweit zurück.", null, null, "§ 327 III lässt die Bereitstellung personenbezogener Daten genügen. Ein zusätzliches Abo ist nicht nötig.", null]}, "P3-vl6-10": {"k": "Für die CD gelten ", "w": ["Abgrenzung nach § 327 V: Körperliche Datenträger, die ausschließlich als Träger digitaler Inhalte dienen (Musik-CD, USB-Stick mit Inhalt), unterfallen den §§ 327 ff.", "Ein leerer USB-Stick dient nicht als Träger bestimmter Inhalte – er ist eine gewöhnliche Ware → §§ 434 ff.", "Ergebnis: CD → §§ 327 ff.; leerer Stick → Kaufrecht."], "o": [null, null, null, "Auch Datenträger sind Leistungsgegenstände mit Mängelhaftung. Es fragt sich nur, ob §§ 327 ff. oder §§ 434 ff. gelten.", "Waren mit digitalen Elementen enthalten Software, die sie zum Funktionieren brauchen. Eine CD ist reiner Datenträger, ein leerer Stick eine normale Ware.", null]}, "P3-vl6-11": {"k": "Es liegt ein Recht", "w": ["Rechtsmangel (§ 435 S. 1): Dritte können in Bezug auf die Sache Rechte gegen den Käufer geltend machen. Eine eingetragene Grundschuld ist ein solches dingliches Recht.", "Der Verkäufer muss die Sache frei von Rechtsmängeln verschaffen (§ 433 I 2). Bei eingetragenen Rechten muss er sie sogar beseitigen, wenn der Käufer sie kennt (§ 442 II).", "Kein Verbrauchsgüterkauf, weil Grundstücke keine Waren sind. Rechte über § 437: zuerst Beseitigung (Löschung), dann Rücktritt, Minderung oder Schadensersatz."], "o": [null, null, null, null, null, null]}, "P3-vl6-12": {"k": "Ein Rechtsmangel l", "w": ["„Kauf bricht nicht Miete“ (§ 566 I): Der Erwerber tritt in den bestehenden Mietvertrag ein. M darf also auch gegenüber K wohnen bleiben.", "Damit kann ein Dritter (M) Rechte in Bezug auf die Sache gegen den Käufer geltend machen → Rechtsmangel (§ 435 S. 1), auch wenn das Recht nur schuldrechtlich ist.", "K wollte selbst einziehen; im Vertrag stand nichts über die Mieter → V haftet nach § 437."], "o": [null, null, null, null, null, null]}, "P3-vl6-13": {"k": "Erschließung zahlt", "w": ["Öffentliche Abgaben und Lasten sind weder Sach- noch Rechtsmangel. § 436 regelt nur, wer sie trägt.", "§ 436 I: Erschließungsbeiträge für Maßnahmen, die bis zum Vertragsschluss bautechnisch begonnen wurden, trägt der Verkäufer – unabhängig davon, wann der Bescheid kommt. Baubeginn Januar, Vertrag 1. 3. → V.", "§ 436 II: Für andere öffentliche Lasten, die nicht eintragungsfähig sind (z. B. Grundsteuer), haftet der Verkäufer nicht."], "o": [null, null, null, null, null, null]}, "P3-vl6-14": {"k": "K darf ablehnen un", "w": ["Vor Gefahrübergang (hier: Übergabe bei Bringschuld) gilt das allgemeine Leistungsstörungsrecht, danach §§ 437 ff.", "Der Verkäufer schuldet eine mangelfreie Sache (§ 433 I 2). Eine Maschine mit großer Delle ist kein ordnungsgemäßes Angebot.", "K darf deshalb die Annahme verweigern, ohne in Annahmeverzug zu geraten, und die Zahlung zurückhalten (§ 320). Der Anspruch auf eine mangelfreie Maschine bleibt."], "o": [null, null, null, null, null, null]}, "P3-vl6-15": {"k": "Nur beim Firmenwag", "w": ["§ 477 I gilt nur beim Verbrauchsgüterkauf: Ein Verbraucher kauft von einem Unternehmer (§ 474 I).", "Firmenwagen: U (Unternehmer) verkauft an K (privat). Auch der Verkauf von Betriebsvermögen erfolgt in Ausübung der gewerblichen Tätigkeit → Verbrauchsgüterkauf → Vermutung greift, auch bei gebrauchten Sachen.", "Rasenmäher: Hier ist die Verbraucherin P Verkäuferin, U Käufer → kein Verbrauchsgüterkauf → keine Vermutung."], "o": [null, null, null, null, null, null]}, "P3-vl6-16": {"k": "R muss die Erkrank", "w": ["Verbrauchsgüterkauf über ein Tier; Tiere werden wie Sachen behandelt (§ 90a S. 3).", "§ 477 I 1: grundsätzlich Vermutung für ein Jahr. Sonderregel § 477 I 2: Beim Kauf eines lebenden Tieres nur sechs Monate.", "Erkrankung zeigt sich nach acht Monaten → keine Vermutung → R muss beweisen, dass sie bei Übergabe vorlag."], "o": [null, null, null, null, null, null]}, "P3-vl6-17": {"k": "V muss eine neue M", "w": ["Nacherfüllung: Der Käufer wählt zwischen Nachbesserung und Neulieferung (§ 439 I); der Verkäufer ist daran gebunden.", "Ausnahmen nur bei Unmöglichkeit (§ 275) oder unverhältnismäßigen Kosten der gewählten Art (§ 439 IV).", "Beide Wege kosten V etwa gleich viel → kein Verweigerungsrecht. Das Gewinninteresse des V zählt nicht."], "o": [null, null, null, null, null, null]}, "P3-vl6-18": {"k": "V kann die Reparat", "w": ["K wählt Reparatur (§ 439 I).", "§ 439 IV: Der Verkäufer kann die gewählte Art verweigern, wenn sie unverhältnismäßige Kosten verursacht – Vergleich mit der anderen Art (relative Unverhältnismäßigkeit).", "Reparatur 40 €, Neugerät 6 € → Reparatur unverhältnismäßig. K bleibt die Neulieferung (§ 439 IV 4)."], "o": [null, null, null, null, null, null]}, "P3-vl6-19": {"k": "V kann den Austaus", "w": ["K wählt Neulieferung (§ 439 I).", "§ 439 IV: Austausch kostet 650 €, Reparatur 30 €; der Schlauchtausch beseitigt den Mangel vollständig und ohne Nachteil für K → Neulieferung unverhältnismäßig.", "V darf den Austausch verweigern und repariert. Ein Rücktritt scheidet aus, solange V die Reparatur anbietet; zudem wäre der Mangel unerheblich (§ 323 V 2)."], "o": [null, null, null, null, null, null]}, "P2-kauf3-10": {"k": "400 € als Schadens", "w": ["Schaden am Handy = Schaden an einem anderen Rechtsgut als der Kaufsache (Mangelfolgeschaden).", "Er lässt sich durch Nacherfüllung nicht beseitigen → Schadensersatz neben der Leistung (§§ 437 Nr. 3, 280 I), ohne Frist.", "Vertretenmüssen: vermutet (§ 280 I 2); H hatte den Rahmen bei der Inspektion fahrlässig nicht beachtet → 400 €."], "o": [null, null, null, "Gegen den Hersteller kommt das ProdHaftG in Betracht. Daneben besteht der vertragliche Anspruch gegen H aus §§ 437 Nr. 3, 280 I.", null, "Minderung gleicht den geringeren Wert des Fahrrads aus. Schäden an anderen Sachen wie dem Handy erfasst sie nicht."]}, "P2-kauf3-11": {"k": "§ 119 II ist ausge", "w": ["Beide hielten das Bild für ein Werk des M → die Urheberschaft war vereinbarte Beschaffenheit (§ 434 II). Eine Kopie weicht davon ab → Sachmangel.", "Anfechtung nach § 119 II (Irrtum über verkehrswesentliche Eigenschaft)? Nach Gefahrübergang verdrängt das Mängelrecht die Anfechtung, weil sonst die besonderen Regeln (Nacherfüllung, Verjährung) umgangen würden.", "§ 123 scheidet aus, weil H gutgläubig war. Ergebnis: K hat Rechte aus § 437."], "o": [null, "Ein Wahlrecht besteht nicht. Nach Gefahrübergang gehen die Mängelrechte der Anfechtung nach § 119 II vor.", "Ein gemeinsamer Irrtum schließt Mängelrechte nicht aus. Die Beschaffenheit „Werk von M“ war vereinbart, die Abweichung ist ein Mangel.", "§ 313 tritt zurück, soweit die Mängelrechte das Risiko regeln. Die Urheberschaft betrifft die Beschaffenheit der Kaufsache.", null, null]}, "P2-kauf3-12": {"k": "Die Nacherfüllung ", "w": ["K wählte Neulieferung; die Ersatzfritteuse hat denselben Defekt, und H lehnt einen weiteren Austausch ab.", "Nacherfüllung fehlgeschlagen bzw. verweigert → Frist für Rücktritt oder Minderung entbehrlich (§ 440 S. 1; beim Verbrauchsgüterkauf zudem § 475d I Nr. 2).", "K kann zurücktreten oder mindern; Schadensersatz bei Vertretenmüssen."], "o": [null, null, "Die Wahl der Neulieferung verbraucht die übrigen Rechte nicht. Scheitert die Nacherfüllung, kann K auf Rücktritt oder Minderung übergehen.", "Die Ersatzsache hat denselben Mangel. Sie ist genauso mangelhaft wie die erste, unabhängig davon, wann der Defekt auftritt.", "Eine mangelhafte Ersatzlieferung ist keine Erfüllung. Die Nacherfüllung ist gescheitert.", "Rücktritt nach misslungener Ersatzlieferung ist gerade der gesetzliche Fall (§ 440). Einen Ausschluss gibt es nicht."]}, "P2-kauf3-13": {"k": "Mangelhaft; V kann", "w": ["Verschimmelter Joghurt vor Ablauf des MHD eignet sich nicht für die gewöhnliche Verwendung (§ 434 III) → Sachmangel.", "Rechtsfolge: Nacherfüllung (§ 439) – ein neuer Joghurt ist problemlos lieferbar.", "Gegner ist der Verkäufer (Supermarkt). Ein Widerrufsrecht gibt es im Laden nicht; der Kassenbon ist nur Beweismittel."], "o": [null, "Auch Lebensmittel sind Waren. Für sie gelten die normalen Mängelrechte.", "Ein Widerrufsrecht gibt es nur bei Fernabsatz oder außerhalb von Geschäftsräumen. Im Supermarkt bestehen aber die Mängelrechte.", "Mängelrechte richten sich immer gegen den Verkäufer, nicht gegen den Hersteller.", "Eine Ersatzlieferung ist bei Joghurt ohne Weiteres möglich. Unmöglich wäre sie nur bei einem Einzelstück.", "Der Kassenbon erleichtert den Beweis des Kaufs, ist aber keine Voraussetzung des Anspruchs."]}, "P2-kauf3-14": {"k": "K hat Mängelrechte", "w": ["Vereinbarte Beschaffenheit „unfallfrei“ (§ 434 II) → reparierter Frontschaden ist ein Mangel.", "Gewährleistungsausschluss zwischen Privatleuten grundsätzlich wirksam. Aber: Nach dem BGH erfasst ein pauschaler Ausschluss nicht die ausdrücklich vereinbarte Beschaffenheit – sonst wäre die Vereinbarung sinnlos.", "Auf Arglist (§ 444) kommt es deshalb nicht an. K hat Mängelrechte."], "o": [null, null, null, null, null, "Eine Garantie wäre ein zusätzlicher Grund. Schon die Beschaffenheitsvereinbarung genügt, weil der pauschale Ausschluss sie nicht erfasst."]}, "P3-vl6-20": {"k": "V kann nur Reparat", "w": ["Gebrauchter Wagen = Stückschuld: geschuldet ist genau dieses Fahrzeug mit seiner Geschichte.", "Nachlieferung eines „gleich alten“ anderen Wagens ist in der Regel unmöglich (§ 275 I) – nur ausnahmsweise möglich, wenn ein wirklich gleichwertiger Ersatz am Markt besteht.", "Die Reparatur des Navis bleibt möglich und geschuldet. Ein Rücktritt kommt erst in Betracht, wenn sie scheitert."], "o": [null, null, null, null, null, null]}, "P3-vl6-21": {"k": "K kann Aus- und Ei", "w": ["Mangel bei Übergabe (Haarrisse angelegt). K hat die Fliesen gemäß Art und Zweck einbauen lassen, ohne den Mangel zu kennen.", "§ 439 III: Verkäufer ersetzt die erforderlichen Aufwendungen für Ausbau und Einbau – verschuldensunabhängig, als Teil der Nacherfüllung.", "Verbrauchsgüterkauf: Vorschuss auf diese Kosten (§ 475 IV nach deinem dtv). Eine Frist ist nicht nötig."], "o": [null, null, null, null, null, null]}, "P3-vl6-22": {"k": "F bekommt nichts, ", "w": ["§ 439 III gilt grundsätzlich auch zwischen Unternehmern.", "§ 439 III 2 verweist auf § 442 I: Der Anspruch ist ausgeschlossen, wenn der Käufer den Mangel kannte – maßgeblich ist dabei der Zeitpunkt des Einbaus.", "F sah die Risse vor dem Verlegen und baute trotzdem ein → kein Anspruch auf Aus- und Einbaukosten. Eine Rüge nach § 377 HGB ändert daran nichts."], "o": [null, null, null, null, null, null]}, "P3-vl6-23": {"k": "K bekommt nichts, ", "w": ["Im Kaufrecht hat der Verkäufer ein Recht zur zweiten Andienung (Vorrang der Nacherfüllung).", "Eine Selbstvornahme mit Kostenersatz kennt nur das Miet- und Werkvertragsrecht (§§ 536a II, 637). Im Kaufrecht bräuchte K Schadensersatz statt der Leistung → erfolglose Frist (§ 281 I).", "Der BGH lehnt auch § 637 analog und § 326 II 2 analog ab → K bekommt nichts."], "o": [null, null, null, null, null, null]}, "P3-vl6-24": {"k": "V kann zurücktrete", "w": ["Verbrauchsgüterkauf: Der Unternehmer muss nacherfüllen innerhalb angemessener Frist ab der Mangelmitteilung (§ 475 V nach deinem dtv).", "Rücktritt ohne Fristsetzung, wenn der Unternehmer trotz Ablaufs einer angemessenen Frist ab Unterrichtung nicht nacherfüllt (§ 475d I Nr. 1).", "V meldete den Mangel per E-Mail (formfrei); H tat drei Monate nichts → Rücktritt möglich."], "o": [null, null, null, null, null, null]}, "P3-vl6-25": {"k": "Als Schadensersatz", "w": ["Schadensart bestimmen: Der Gewinnausfall entstand durch den Mangel selbst während der zwei Tage; auch die Reparatur am dritten Tag beseitigt ihn nicht.", "Das ist Schadensersatz neben der Leistung (§§ 437 Nr. 3, 280 I) – nach dem BGH ohne Verzug (Betriebsausfallschaden).", "Vertretenmüssen: V hat den Fehler bei der Endkontrolle fahrlässig übersehen (und es wird ohnehin vermutet)."], "o": [null, null, null, null, null, null]}, "P3-vl6-26": {"k": "K bekommt die 600 ", "w": ["Schaden: Mietkosten, weil V die Nacherfüllung drei Wochen verzögert.", "Nach dem Skript: Verzögerungsschaden (§§ 437 Nr. 3, 280 I, II, 286) – Verzug mit der Nacherfüllung; die Mahnung liegt in der Regel schon im schriftlichen Nacherfüllungsverlangen.", "Vertretenmüssen der Verzögerung: Unbegründetes Bestreiten entlastet V nicht. (Nach BGH ließe sich ein solcher Nutzungsausfall auch direkt über § 280 I begründen – das Ergebnis ist gleich.)"], "o": [null, null, null, null, null, null]}, "P3-vl6-27": {"k": "K kann Ersatz nach", "w": ["Stromschlag durch Isolationsfehler → Schaden an Gesundheit = anderes Rechtsgut als die Kaufsache (Mangelfolgeschaden).", "Anspruch: §§ 437 Nr. 3, 280 I – Schadensersatz neben der Leistung, keine Frist (Nacherfüllung beseitigt die Verletzung nicht).", "Vertretenmüssen: V hätte den Fehler bei der Prüfung erkennen können. Daneben § 823 I und ggf. Hersteller nach ProdHaftG."], "o": [null, null, null, null, null, null]}, "P3-vl6-28": {"k": "Aus §§ 280 I, 241 ", "w": ["Die Küchenfront wurde nicht durch den Mangel der Haube beschädigt, sondern durch den Monteur bei der Nacherfüllung.", "Damit geht es nicht um Mängelrecht, sondern um die Verletzung einer Rücksichtnahmepflicht (§ 241 II) im bestehenden Vertrag.", "Anspruch: §§ 280 I, 241 II; das Verschulden des Monteurs wird V zugerechnet (§ 278)."], "o": [null, null, null, null, null, null]}, "P3-vl6-29": {"k": "K kann den Minderw", "w": ["Nach zwei gescheiterten Nachbesserungen gilt die Nacherfüllung als fehlgeschlagen (§ 440 S. 2) → Frist entbehrlich.", "K behält den Wagen und verlangt den Minderwert → „kleiner“ Schadensersatz statt der Leistung (§§ 437 Nr. 3, 280 I, III, 281).", "Vertretenmüssen wird vermutet. Ein Rücktritt ist keine Voraussetzung; alternativ könnte K mindern."], "o": [null, null, null, null, null, null]}, "P3-vl6-30": {"k": "Als Nichtleistung:", "w": ["Grundsatz: Falschlieferung (aliud) steht einem Sachmangel gleich (§ 434 V).", "Skript: Das gilt nicht, wenn der Verkäufer mutwillig etwas anderes liefert – dann liegt gar kein Erfüllungsversuch vor, sondern Nichtleistung.", "Folge: K kann weiter Erfüllung mit dem Markengerät verlangen (§ 433 I), nicht nur Mängelrechte."], "o": [null, null, null, null, null, null]}, "P3-vl6-31": {"k": "V muss die ersetzt", "w": ["Bei Nachlieferung kann der Verkäufer die mangelhafte Sache zurückverlangen (§ 439 VI 1).", "§ 439 VI 2: Der Verkäufer hat die ersetzte Sache auf seine Kosten zurückzunehmen.", "K muss die Lampe nur zur Verfügung stellen (§ 439 V), nicht auf eigene Kosten zurückschicken."], "o": [null, null, null, null, null, null]}, "P3-vl6-32": {"k": "K kann die Zahlung", "w": ["Kauf = gegenseitiger Vertrag. Der Verkäufer schuldet eine mangelfreie Sache (§ 433 I 2).", "Solange V nicht nacherfüllt, kann K seine Gegenleistung zurückhalten – Einrede des nicht erfüllten Vertrags (§ 320 I).", "Eine Frist ist dafür nicht nötig; die Fälligkeit des Kaufpreises hindert die Einrede nicht."], "o": [null, null, null, null, null, null]}, "P3-vl6-33": {"k": "S irrt: § 437 ist ", "w": ["Rechtsgrundverweisung: Verweist auf eine Norm mit ihren Voraussetzungen. Rechtsfolgenverweisung: übernimmt nur die Rechtsfolge.", "§ 437 ist eine Rechtsgrundverweisung: Wer zurücktreten will, muss z. B. die Frist des § 323 I prüfen; wer Schadensersatz will, das Vertretenmüssen nach § 280 I 2.", "S irrt also – die Voraussetzungen der verwiesenen Normen bleiben zu prüfen."], "o": [null, null, null, null, null, null]}, "P3-vl6-34": {"k": "Der Ausschluss ist", "w": ["Objektive Aktualisierungspflicht (§ 475b IV Nr. 2) kann beim Verbrauchsgüterkauf nur unter § 476 I 2 abbedungen werden.", "Voraussetzungen: (1) Verbraucher vor Vertragsschluss eigens informiert, (2) Abweichung ausdrücklich und gesondert vereinbart.", "H hat eigens mitgeteilt; V hat ein gesondertes Feld angekreuzt → wirksam → keine Updatepflicht, kein Mangel."], "o": [null, null, null, null, null, null]}, "fb-7-rt": {"k": "Kein Rücktritt; K ", "w": ["Frist ist abgelaufen (bzw. wegen Verweigerung entbehrlich). Trotzdem: Rücktritt ist ausgeschlossen, wenn die Pflichtverletzung unerheblich ist (§ 323 V 2).", "Erheblichkeit: Interessenabwägung; Faustregel des BGH: Mangelbeseitigungskosten unter ca. 5 % des Kaufpreises → unerheblich. 80 € bei 30.000 € liegen weit darunter.", "Was bleibt: Minderung (§ 441 I 2 – gerade auch bei unerheblichen Mängeln) oder kleiner Schadensersatz. Großer Schadensersatz scheitert ebenfalls (§ 281 I 3)."], "o": [null, null, null, null, null, null]}, "P2-kauf3-0": {"k": "Die Verkürzung auf", "w": ["Verjährung Mängelansprüche grundsätzlich 2 Jahre (§ 438 I Nr. 3).", "Beim Verbrauchsgüterkauf über gebrauchte Sachen ist eine Verkürzung auf 1 Jahr zulässig, wenn der Verbraucher vor Vertragsschluss eigens darauf hingewiesen und die Verkürzung ausdrücklich und gesondert vereinbart wurde (§ 476 II).", "K wurde eigens hingewiesen und hat gesondert zugestimmt → wirksam. Nach Ablauf eines Jahres kann H die Einrede der Verjährung erheben (§ 214 I)."], "o": [null, null, "Auch Mängel, die schon bei Übergabe angelegt waren, unterliegen der (verkürzten) Verjährung. Nach Ablauf kann H die Leistung verweigern.", "Die Verkürzung betrifft alle Mängelansprüche, nicht nur erkennbare Mängel.", "§ 476 II verlangt Hinweis und gesonderte Vereinbarung, aber keinen Preisnachlass.", null]}, "P2-kauf3-1": {"k": "Die Maschine ist m", "w": ["Subjektive Anforderung (§ 434 II 1 Nr. 1): Verkauft wurde eine „neue“ Maschine – „neu“ ist vereinbarte Beschaffenheit.", "Ein Rückläufer mit Gebrauchsspuren ist nicht neu → Sachmangel, auch wenn er technisch einwandfrei ist.", "Daneben kann V als Verbraucherin im Fernabsatz auch widerrufen – beide Rechte bestehen nebeneinander."], "o": [null, null, "Widerrufsrecht und Mängelrechte bestehen unabhängig voneinander. V kann wählen.", "Was im Handel üblich ist, ändert nichts an der ausdrücklichen Vereinbarung „neu“.", null, null]}, "P2-kauf3-2": {"k": "K kann ohne Frists", "w": ["Mangel: vereinbarte Laufleistung 85.000 km, tatsächlich 190.000 km.", "Nacherfüllung unmöglich: Die Laufleistung lässt sich nicht beheben, und ein gleichwertiges Ersatzfahrzeug gibt es nicht (§ 275 I).", "Bei unbehebbarem Mangel kann der Käufer ohne Fristsetzung zurücktreten (§§ 437 Nr. 2, 326 V) – verschuldensunabhängig. Die Abweichung ist erheblich."], "o": [null, null, null, null, "Eine Reparatur des Tachos ändert nichts daran, dass das Fahrzeug tatsächlich 190.000 km gelaufen ist. Der Mangel ist nicht behebbar.", "Rücktritt und Anfechtung sind getrennte Wege. Für den Rücktritt muss K nicht zusätzlich anfechten."]}, "P2-kauf3-3": {"k": "Kein Rücktritt, we", "w": ["Mangel liegt vor, Frist ist abgelaufen.", "Rücktritt ausgeschlossen bei unerheblicher Pflichtverletzung (§ 323 V 2). Faustregel: Beseitigungskosten unter ca. 5 % des Kaufpreises → 120 € bei 30.000 € (0,4 %) ist unerheblich.", "Minderung bleibt ausdrücklich möglich (§ 441 I 2), ebenso Nacherfüllung und kleiner Schadensersatz."], "o": [null, null, null, null, null, "Weitere Fristen machen einen geringfügigen Kratzer nicht erheblich. Die Unerheblichkeit sperrt den Rücktritt dauerhaft."]}, "P2-kauf3-4": {"k": "90 € Schadensersat", "w": ["Selbstvornahme ist im Kaufrecht als solches nicht vorgesehen. Aber: Nach erfolglosem Fristablauf kann K Schadensersatz statt der Leistung verlangen (§§ 437 Nr. 3, 280 I, III, 281).", "Die erforderlichen Reparaturkosten sind ein solcher Schaden: Sie ersetzen die ausgebliebene Nacherfüllung.", "Vertretenmüssen wird vermutet (§ 280 I 2) – H müsste sich entlasten. Ergebnis: 90 €."], "o": [null, null, null, "Nach Fristablauf muss K die Reparatur nicht mehr mit H abstimmen. Eine Kürzung sieht das Gesetz nicht vor.", null, "Die Rücksendung des Druckers ist keine Voraussetzung für Schadensersatz statt der Leistung."]}, "P2-kauf3-5": {"k": "K hat seine Rechte", "w": ["Beiderseitiger Handelskauf → § 377 HGB.", "Untersuchung bei Lieferung: Stichproben genügten; der Fehler war versteckt → bis zur Entdeckung kein Rechtsverlust.", "Versteckter Mangel muss aber unverzüglich nach Entdeckung gerügt werden (§ 377 III HGB). Drei Wochen sind nicht unverzüglich → die Ware gilt auch in Ansehung dieses Mangels als genehmigt."], "o": [null, null, null, null, "Gerade der Weiterverkauf ist der typische Handelskauf. § 377 HGB gilt für jeden beiderseitigen Handelskauf.", null]}, "P2-kauf3-6": {"k": "Die Couch ist mang", "w": ["Montage war vom Verkäufer übernommen (Lieferung „aufgebaut“).", "§ 434 IV: Die Sache ist mangelhaft, wenn die Montage durch den Verkäufer unsachgemäß durchgeführt wurde.", "Der abgebrochene Fuß beruht auf falschem Anschrauben → Sachmangel → Rechte aus § 437, zuerst Nacherfüllung."], "o": [null, null, "Die übernommene Montage ist Teil des Kaufvertrags; Fehler dabei sind nach § 434 IV Sachmängel. Ein eigener Werkvertrag ist nicht nötig.", "Verbraucher trifft keine Prüf- oder Rügepflicht. Grenze ist nur die Verjährung.", "Der falsch montierte Fuß ist ein Sachmangel. K hat deshalb alle Rechte aus § 437, nicht nur Schadensersatz.", "§ 434 IV gilt für jede vom Verkäufer übernommene Montage, auch wenn sie im Preis enthalten ist."]}, "P2-kauf3-7": {"k": "Die Zuweniglieferu", "w": ["Seit 2022 gehört die Menge zur vereinbarten Beschaffenheit (§ 434 II 2) → 40 statt 50 Flaschen ist ein Sachmangel.", "Rechtsfolge: Nacherfüllung durch Nachlieferung der 10 Flaschen (§§ 437 Nr. 1, 439).", "Bis dahin kann K den Kaufpreis insoweit zurückhalten (§ 320). Rücktritt erst nach erfolgloser Frist."], "o": [null, "Die Annahme einer zu geringen Lieferung ändert den Vertrag nicht. Geschuldet bleiben 50 Flaschen.", null, null, null, "Wein derselben Sorte ist Gattungsware und lässt sich problemlos nachliefern."]}, "P2-kauf3-8": {"k": "V hat keine gesetz", "w": ["Mängelrechte setzen einen Mangel voraus – die Jacke ist mangelfrei.", "Ein gesetzliches Widerrufsrecht besteht nur bei Fernabsatz oder außerhalb von Geschäftsräumen, nicht beim Kauf im Laden.", "Gefallen nicht mehr = Motivirrtum, keine Anfechtung. Der Umtausch gegen Gutschein ist reine Kulanz."], "o": [null, null, null, null, "Ein gesetzliches Umtauschrecht gibt es nicht. Umtausch ist Kulanz oder vertraglich vereinbart.", "Nacherfüllung setzt einen Mangel voraus. Persönliches Nichtgefallen ist kein Mangel."]}, "P2-kauf3-9": {"k": "Der Laptop war bei", "w": ["Maßgeblicher Zeitpunkt für die Mangelfreiheit: Gefahrübergang (§ 434 I) – beim Kauf die Übergabe an den Käufer (§ 446 S. 1).", "Der Laptop fiel dem Verkäufer kurz vor der Übergabe aus der Hand → bei Übergabe hatte er bereits den Sprung → mangelhaft.", "K hat die Rechte aus § 437. § 442 betrifft nur die Kenntnis bei Vertragsschluss, nicht bei Übergabe."], "o": [null, null, "Neben einer möglichen deliktischen Haftung bestehen vertragliche Mängelrechte gegen H, weil der Laptop bei Übergabe mangelhaft war.", null, null, "Wer eine erkennbar beschädigte Sache bei Übergabe mitnimmt, behält seine Rechte. § 442 knüpft an den Vertragsschluss an."]}, "fb-3-obl": {"k": "I hat die Mängelre", "w": ["Beiderseitiger Handelskauf (zwei GmbHs) → § 377 HGB: unverzüglich untersuchen und erkennbare Mängel rügen.", "I hat ungeprüft gelagert; der Gehäuseriss war erkennbar → nach fünf Wochen zu spät → Ware gilt als genehmigt (§ 377 II HGB). Alle Mängelrechte entfallen, auch Minderung.", "Untersuchung und Rüge sind Obliegenheiten, keine Pflichten: Ihre Verletzung führt nur zum Rechtsverlust, nicht zu Schadensersatz."], "o": [null, null, null, null, null, null]}, "fb-7-reg": {"k": "Ja, aus § 445a I, ", "w": ["H musste gegenüber V nacherfüllen (neue Sache, Herstellungsfehler).", "Unternehmerrückgriff (§ 445a I): H kann von seinem Lieferanten G die Aufwendungen ersetzt verlangen, die er nach § 439 II, III tragen musste – wenn der Mangel schon beim Übergang auf H vorhanden war.", "Aufwendungsersatz ist verschuldensunabhängig und braucht keine Frist. Unter Kaufleuten bleibt § 377 HGB zu beachten (§ 445a IV)."], "o": [null, null, null, null, null, null]}});
